export const SOURCE_PARTS: Record<string, string> = {
  "book-jacket:AUTHOR": "const AUTHOR = 'Kim Soon-ja'",
  "book-jacket:AUTHOR_KO": "const AUTHOR_KO = '김순자'",
  "book-jacket:blurb": "const blurb = (size = '3.5cqw'): CSSProperties => ({\n  margin: 0,\n  fontSize: size,\n  lineHeight: 1.52,\n  letterSpacing: '-0.008em',\n})",
  "book-jacket:IMPRINT": "const IMPRINT = 'Saedol Press'",
  "book-jacket:ISBN_DIGITS": "/** 978-89-94963-01-3: the Bookland prefix, Korea's 89 group, then the title. */\nconst ISBN_DIGITS = '978899496301'",
  "book-jacket:ISBN_TEXT": "const ISBN_TEXT = 'ISBN 978-89-94963-01-3'",
  "book-jacket:JacketBack": "/**\n * Back board: the apparatus. A pull quote, the flap copy, an author line, and\n * the foot that every book has - imprint, price, and the barcode in the white\n * box it is legally required to be scannable from.\n */\nexport function JacketBack({ cloth }: { cloth: string }) {\n  const t = jacketTone(cloth)\n  return (\n    <Sheet tone={t} style={{ flexDirection: 'column', padding: '7cqw', gap: '4cqw' }}>\n      <Micro style={{ color: t.accent }}>Memoir · 344 pages</Micro>\n\n      <p\n        style={{\n          margin: 0,\n          fontSize: '6.2cqw',\n          fontWeight: 600,\n          letterSpacing: '-0.03em',\n          lineHeight: 1.14,\n        }}\n      >\n        “I was sixty before I learned to say the word I wanted.”\n      </p>\n\n      <div style={{ height: '0.4cqw', background: t.accent, flex: 'none', opacity: 0.5 }} />\n\n      <div style={{ display: 'flex', flexDirection: 'column', gap: '2.6cqw' }}>\n        <p style={blurb()}>\n          Kim Soon-ja was born in a market town in 1938, the fourth daughter in a house that had\n          wanted sons. She was nine when the country divided, nineteen when she married a man she\n          had met twice, and forty-one when she opened the shop on Bongcheon-ro that fed her family\n          for thirty years.\n        </p>\n        <p style={blurb()}>\n          She began writing this book at eighty-two, in a school notebook, in the hour before the\n          shop opened. It is an account of a century in one woman&apos;s hands: what the war took,\n          what the winters cost, what she refused to hand on to her daughters.\n        </p>\n        <p style={{ ...blurb('3.2cqw'), opacity: 0.66 }}>\n          Kim Soon-ja lives in Seoul, two streets from the shop. This is her first and, she insists,\n          her only book.\n        </p>\n      </div>\n\n      <div style={{ flex: 1, minHeight: 0 }} />\n\n      <div style={{ display: 'flex', alignItems: 'flex-end', justifyContent: 'space-between', gap: '4cqw' }}>\n        <div style={{ display: 'flex', flexDirection: 'column', gap: '1.4cqw' }}>\n          <span style={{ fontSize: '4.4cqw', fontWeight: 700, letterSpacing: '-0.02em', lineHeight: 1 }}>\n            {IMPRINT}\n          </span>\n          <Micro style={{ fontSize: '2.5cqw', opacity: 0.6 }}>{AUTHOR_KO} · 새돌출판사</Micro>\n          <span style={{ fontSize: '2.6cqw', opacity: 0.6, letterSpacing: '0.02em' }}>{ISBN_TEXT}</span>\n        </div>\n\n        {/* A barcode is only a barcode on white, whatever the jacket is. */}\n        <div\n          style={{\n            flex: 'none',\n            background: '#ffffff',\n            padding: '1.6cqw 1.8cqw 1.2cqw',\n            display: 'flex',\n            flexDirection: 'column',\n            alignItems: 'stretch',\n            gap: '0.8cqw',\n          }}\n        >\n          <span\n            style={{\n              fontFamily: FONT,\n              fontSize: '2.1cqw',\n              fontWeight: 600,\n              letterSpacing: '0.06em',\n              color: INK,\n            }}\n          >\n            ₩18,000\n          </span>\n          <Ean13 digits={ISBN_DIGITS} color={INK} style={{ width: '30cqw', height: 'auto' }} />\n        </div>\n      </div>\n    </Sheet>\n  )\n}",
  "book-jacket:JacketCover": "/**\n * Front board. Title at the head, one band of pattern under it as a rule with\n * some weather in it, and the portrait rising into the lower two-thirds.\n */\nexport function JacketCover({ cloth }: { cloth: string }) {\n  const t = jacketTone(cloth)\n  return (\n    <Sheet tone={t} style={{ flexDirection: 'column', padding: '7cqw', position: 'relative' }}>\n      <Portrait />\n\n      {/* the type block sits over the photograph, so it is its own layer */}\n      <div style={{ position: 'relative', display: 'flex', flexDirection: 'column', gap: '3cqw' }}>\n        <Micro style={{ color: t.accent }}>A memoir</Micro>\n        <h2\n          style={{\n            margin: 0,\n            fontSize: '15.5cqw',\n            fontWeight: 700,\n            letterSpacing: '-0.045em',\n            lineHeight: 0.94,\n            whiteSpace: 'pre-line',\n          }}\n        >\n          {TITLE.join('\\n')}\n        </h2>\n        <span style={{ fontSize: '5.4cqw', fontWeight: 500, letterSpacing: '-0.01em', opacity: 0.62 }}>\n          {TITLE_KO}\n        </span>\n      </div>\n\n      {/* The ornament breaks the left margin and stops short of the portrait.\n          Run full-bleed it crossed her face, which is the one thing a jacket\n          may not do; anchored left it reads as the rule it is standing in for. */}\n      <div\n        style={{\n          position: 'relative',\n          marginTop: '4cqw',\n          marginLeft: '-7cqw',\n          width: '48cqw',\n          height: '11cqw',\n          flex: 'none',\n          borderTop: `0.5cqw solid ${t.accent}`,\n        }}\n      >\n        <Pattern pattern={epicentre} seed=\"jacket-band\" palette={t.palette} grid=\"5x2\" />\n      </div>\n\n      <div style={{ flex: 1, minHeight: 0 }} />\n\n      <div style={{ position: 'relative', display: 'flex', flexDirection: 'column', gap: '1.6cqw' }}>\n        <span\n          style={{\n            fontSize: '6.6cqw',\n            fontWeight: 700,\n            letterSpacing: '-0.03em',\n            lineHeight: 1.02,\n            // Stops short of where the portrait's left edge lands, so the two\n            // never meet at the foot whatever the name's length.\n            maxWidth: '36cqw',\n          }}\n        >\n          {AUTHOR}\n        </span>\n        <Micro style={{ fontSize: '2.8cqw', opacity: 0.6 }}>{IMPRINT}</Micro>\n      </div>\n    </Sheet>\n  )\n}",
  "book-jacket:JacketSpine": "/**\n * The spine - the only face a shelf shows.\n *\n * The strip is tall and thin, so the type is laid out across it and the whole\n * line turned a quarter-turn: `rotate(90deg)` reads top-to-bottom, which is\n * how both Korean and American spines are set (a British one would run the\n * other way). The rotated line's own length is the book's height, and it is\n * sized in `cqw` - the spine's thickness - because that is what constrains a\n * spine's type: 17cqw of a 27 mm backbone is about 4.6 mm of cap height,\n * which is what a trade hardback carries.\n */\nexport function JacketSpine({ cloth }: { cloth: string }) {\n  const t = jacketTone(cloth)\n  return (\n    <Sheet tone={t} style={{ alignItems: 'center', justifyContent: 'center', overflow: 'hidden' }}>\n      <div\n        style={{\n          transform: 'rotate(90deg)',\n          whiteSpace: 'nowrap',\n          display: 'flex',\n          alignItems: 'baseline',\n          gap: '11cqw',\n          lineHeight: 1,\n        }}\n      >\n        <span style={{ fontSize: '20cqw', fontWeight: 600, letterSpacing: '0.02em' }}>{AUTHOR}</span>\n        <span style={{ fontSize: '25cqw', fontWeight: 700, letterSpacing: '-0.02em' }}>\n          {TITLE.join(' ')}\n        </span>\n        <span\n          style={{\n            fontSize: '14cqw',\n            fontWeight: 600,\n            letterSpacing: '0.16em',\n            textTransform: 'uppercase',\n            color: t.accent,\n          }}\n        >\n          {IMPRINT}\n        </span>\n      </div>\n    </Sheet>\n  )\n}",
  "book-jacket:jacketTone": "/**\n * The jacket, given the binding cloth underneath it.\n *\n * The cloth becomes the accent - the rule, the kicker, the pattern's second\n * ink - so all four bindings print one design. A cloth too pale to read on\n * cream (the bone binding) falls back to the house indigo rather than\n * printing an invisible title; a jacket is not obliged to match its boards,\n * and an unreadable accent is not a design choice.\n */\nfunction jacketTone(cloth: string): Tone {\n  const accent = luminance(cloth) > 0.42 ? '#2f4a6d' : cloth\n  return { ground: PAPER, text: INK, accent, palette: [PAPER, accent, INK] }\n}",
  "book-jacket:luminance": "/** sRGB relative luminance, 0-1. Duplicated from `swiss-art` only because that one is not exported. */\nfunction luminance(hex: string): number {\n  const h = hex.replace('#', '')\n  const n =\n    h.length === 3\n      ? [...h].map((c) => Number.parseInt(c + c, 16))\n      : [0, 2, 4].map((i) => Number.parseInt(h.slice(i, i + 2), 16))\n  const [r, g, b] = n.map((v) => {\n    const c = v / 255\n    return c <= 0.04045 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4\n  }) as [number, number, number]\n  return 0.2126 * r + 0.7152 * g + 0.0722 * b\n}",
  "book-jacket:Micro": "/** Uppercase micro-type, set in the jacket's own tracking. */\nfunction Micro({ children, style }: { children: ReactNode; style?: CSSProperties }) {\n  return (\n    <span\n      style={{\n        fontSize: '3.2cqw',\n        fontWeight: 600,\n        letterSpacing: '0.2em',\n        textTransform: 'uppercase',\n        lineHeight: 1,\n        ...style,\n      }}\n    >\n      {children}\n    </span>\n  )\n}",
  "book-jacket:PAPER": "/** Uncoated cream stock - what a literary hardback's jacket is printed on. */\nconst PAPER = '#efe9dd'",
  "book-jacket:Portrait": "/**\n * The cut-out portrait, cropped by the jacket's edges.\n *\n * Anchored to the bottom-right corner and running off both of them, at a\n * width that leaves the lower left to the author's name. `object-position`\n * is top-left so that when the box is narrower than the photo it is her\n * shoulder that leaves the sheet, not her face.\n */\nfunction Portrait() {\n  return (\n    // eslint-disable-next-line @next/next/no-img-element\n    <img\n      src={asset('/art/halmoni.webp')}\n      alt=\"\"\n      draggable={false}\n      style={{\n        position: 'absolute',\n        right: '-3cqw',\n        bottom: 0,\n        width: '58cqw',\n        // 860 x 1281 in the file; held here so the aspect never depends on load order\n        aspectRatio: '860 / 1281',\n        objectFit: 'cover',\n        objectPosition: '0% 0%',\n        pointerEvents: 'none',\n      }}\n    />\n  )\n}",
  "book-jacket:TITLE": "const TITLE = ['Spring', 'Comes', 'Late']",
  "book-jacket:TITLE_KO": "const TITLE_KO = '봄은 늦게 온다'",
  "carton-art:Badge": "/**\n * The dairy's badge: an oval, the name in serifs and \"DAIRY\" spaced out under\n * it - the shape a co-op has had on its trucks since before it had a website.\n * `size` is the width in cqw; everything inside is a fraction of it.\n */\nfunction Badge({ size, onBand }: { size: number; onBand?: boolean }) {\n  return (\n    <div\n      style={{\n        width: `${size}cqw`,\n        height: `${size * 0.52}cqw`,\n        borderRadius: '50%',\n        background: CREAM,\n        border: `${size * 0.016}cqw solid ${onBand ? CREAM : RED}`,\n        boxShadow: onBand ? `0 0 0 ${size * 0.02}cqw ${RED}` : `inset 0 0 0 ${size * 0.012}cqw ${CREAM}, inset 0 0 0 ${size * 0.024}cqw ${RED}`,\n        display: 'flex',\n        flexDirection: 'column',\n        alignItems: 'center',\n        justifyContent: 'center',\n        color: NAVY,\n        flex: 'none',\n        lineHeight: 1,\n      }}\n    >\n      <span style={{ fontFamily: SERIF, fontStyle: 'italic', fontSize: `${size * 0.19}cqw`, letterSpacing: '-0.01em', whiteSpace: 'nowrap' }}>\n        Harlow Valley\n      </span>\n      <span style={{ fontFamily: FONT, fontWeight: 700, fontSize: `${size * 0.075}cqw`, letterSpacing: '0.34em', marginTop: `${size * 0.05}cqw`, color: RED }}>\n        DAIRY\n      </span>\n      <span style={{ fontFamily: FONT, fontWeight: 600, fontSize: `${size * 0.055}cqw`, letterSpacing: '0.18em', marginTop: `${size * 0.035}cqw`, opacity: 0.75 }}>\n        EST. 1948 · VERMONT\n      </span>\n    </div>\n  )\n}",
  "carton-art:body": "const body = (size = '3.3cqw', extra?: CSSProperties): CSSProperties => ({\n  margin: 0,\n  fontSize: size,\n  lineHeight: 1.36,\n  ...extra,\n})",
  "carton-art:CartonBack": "/** The back: the rest of the range, and the fun facts for whoever is reading at breakfast. */\nexport function CartonBack({ material }: { material: string }) {\n  const { ink } = dairyInk(material)\n  const facts = [\n    'A dairy cow drinks up to 50 gallons of water a day - a bathtub’s worth.',\n    'One glass of milk has as much calcium as ten cups of raw spinach.',\n    'Milk is about 87 % water. The other 13 % is the fat, protein, sugar and minerals you drink it for.',\n  ]\n  return (\n    <Face material={material} style={{ gap: '2.6cqw' }}>\n      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'baseline' }}>\n        <Micro style={{ color: RED, fontSize: '2.8cqw' }}>Also from Harlow Valley</Micro>\n        <Micro style={{ fontSize: '2.8cqw', opacity: 0.72 }}>Look for the colour</Micro>\n      </div>\n      <div style={{ fontFamily: SERIF, fontSize: '9cqw', lineHeight: 1.05, letterSpacing: '-0.015em' }}>\n        Something for everyone at the table.\n      </div>\n      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '3cqw', alignItems: 'end', padding: '1cqw 2cqw 0' }}>\n        <MiniCarton color=\"#1a5fb4\" pct=\"2%\" label=\"Reduced fat\" ink={ink} />\n        <MiniCarton color=\"#2e8b57\" pct=\"1%\" label=\"Lowfat\" ink={ink} />\n        <MiniCarton color=\"#6b3fa0\" pct=\"0%\" label=\"Fat free\" ink={ink} />\n      </div>\n      <div\n        style={{\n          border: `0.5cqw solid ${ink}`,\n          borderRadius: '3cqw',\n          padding: '3.4cqw 4cqw 3.8cqw',\n          display: 'grid',\n          gap: '2cqw',\n        }}\n      >\n        <Micro style={{ color: RED, fontSize: '2.8cqw' }}>Did you know?</Micro>\n        <ol style={{ margin: 0, padding: 0, listStyle: 'none', display: 'grid', gap: '1.8cqw' }}>\n          {facts.map((fact, i) => (\n            <li key={fact} style={{ display: 'flex', gap: '2.4cqw', ...body('3.2cqw') }}>\n              <span style={{ color: RED, fontWeight: 800, fontVariantNumeric: 'tabular-nums', flex: 'none' }}>{i + 1}</span>\n              <span>{fact}</span>\n            </li>\n          ))}\n        </ol>\n      </div>\n      <div style={{ display: 'flex', gap: '3.5cqw', alignItems: 'stretch', padding: '0.6cqw 0.5cqw 0' }}>\n        <div style={{ flex: 1, display: 'grid', gap: '1.8cqw', alignContent: 'start' }}>\n          <Micro style={{ color: RED, fontSize: '2.8cqw' }}>Serving suggestion</Micro>\n          <div style={{ fontFamily: SERIF, fontSize: '6.6cqw', lineHeight: 1, letterSpacing: '-0.01em' }}>Hot cocoa for two</div>\n          <ol style={{ margin: 0, padding: 0, listStyle: 'none', display: 'grid', gap: '1.4cqw' }}>\n            {[\n              'Warm 2 cups of whole milk over low heat. Never let it boil.',\n              'Whisk in 3 tbsp cocoa and 2 tbsp sugar until smooth.',\n              'Pour, top with marshmallows, and hand one over.',\n            ].map((step, i) => (\n              <li key={step} style={{ display: 'flex', gap: '2.2cqw', ...body('3.1cqw') }}>\n                <span style={{ color: RED, fontWeight: 800, fontVariantNumeric: 'tabular-nums', flex: 'none' }}>{i + 1}</span>\n                <span>{step}</span>\n              </li>\n            ))}\n          </ol>\n        </div>\n        <div style={{ width: '24cqw', flex: 'none' }}>\n          <Mug ink={ink} />\n        </div>\n      </div>\n      <div style={{ flex: 1 }} />\n      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-end', gap: '3cqw' }}>\n        <Badge size={34} />\n        <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'flex-end', gap: '1.4cqw', textAlign: 'right' }}>\n          <RecycleMark color={ink} size=\"6cqw\" />\n          <Micro style={{ fontSize: '2.3cqw', opacity: 0.78, lineHeight: 1.3 }}>\n            Paperboard carton · Cap 2 HDPE\n            <br />\n            Recycle where facilities exist\n          </Micro>\n        </div>\n      </div>\n    </Face>\n  )\n}",
  "carton-art:CartonFacts": "/** The right side: Nutrition Facts, ingredients, storage, the pledge, the UPC. */\nexport function CartonFacts({ material }: { material: string }) {\n  const { ink } = dairyInk(material)\n  return (\n    <Face material={material} style={{ gap: '2cqw' }}>\n      <NutritionFacts\n        fontSize=\"2.6cqw\"\n        servings=\"8\"\n        servingSize=\"1 cup (240mL)\"\n        calories=\"150\"\n        rows={[\n          { label: 'Total Fat', amount: '8g', dv: '10%', bold: true },\n          { label: 'Saturated Fat', amount: '5g', dv: '25%', indent: 1 },\n          { label: 'Trans Fat', amount: '0g', indent: 1 },\n          { label: 'Cholesterol', amount: '35mg', dv: '12%', bold: true },\n          { label: 'Sodium', amount: '125mg', dv: '5%', bold: true },\n          { label: 'Total Carbohydrate', amount: '12g', dv: '4%', bold: true },\n          { label: 'Dietary Fiber', amount: '0g', dv: '0%', indent: 1 },\n          { label: 'Total Sugars', amount: '12g', indent: 1 },\n          { label: 'Includes 0g Added Sugars', amount: '', dv: '0%', indent: 2 },\n          { label: 'Protein', amount: '8g', dv: '16%', bold: true },\n        ]}\n        micros={[\n          { label: 'Vitamin D', amount: '2.5mcg', dv: '15%' },\n          { label: 'Calcium', amount: '300mg', dv: '25%' },\n          { label: 'Iron', amount: '0mg', dv: '0%' },\n          { label: 'Potassium', amount: '380mg', dv: '8%' },\n          { label: 'Vitamin A', amount: '90mcg', dv: '10%' },\n        ]}\n      />\n      <p style={body('3cqw')}>\n        <strong>INGREDIENTS:</strong> GRADE A MILK, VITAMIN D3.\n      </p>\n      <p style={body('3cqw')}>\n        <strong>KEEP REFRIGERATED.</strong> Sell by date on top. For best taste use within 7 days of opening.\n      </p>\n      <p style={body('2.5cqw', { opacity: 0.8 })}>\n        *Our farmers pledge not to use artificial growth hormones. No significant difference has been shown\n        between milk derived from rBST-treated and non-rBST-treated cows.\n      </p>\n      <div style={{ flex: 1 }} />\n      <div style={{ display: 'flex', alignItems: 'flex-end', justifyContent: 'space-between', gap: '3cqw' }}>\n        {/* A scanner wants dark bars on a light ground whatever the board, so the\n            code prints on its own white patch - as it does on a kraft carton. */}\n        <div style={{ background: '#ffffff', padding: '1.6cqw 1.2cqw 0.4cqw', width: '36cqw', boxSizing: 'border-box', flex: 'none' }}>\n          <UpcA digits=\"07123456789\" color=\"#111111\" />\n        </div>\n        <RecycleMark\n          color={ink}\n          size=\"7.5cqw\"\n          label={\n            <Micro style={{ fontSize: '2.3cqw', lineHeight: 1.25 }}>\n              Please\n              <br />\n              recycle\n            </Micro>\n          }\n        />\n      </div>\n      <Micro style={{ fontSize: '2.35cqw', opacity: 0.78 }}>Distributed by Harlow Valley Dairy Co-op · Harlow, VT 05468 · Plant 50-2117</Micro>\n    </Face>\n  )\n}",
  "carton-art:CartonFront": "/** The front: the red band and badge, \"Whole Milk\", the farm, the size. */\nexport function CartonFront({ material }: { material: string }) {\n  const { ink, onInk } = dairyInk(material)\n  return (\n    <Face material={material} style={{ padding: 0, gap: 0 }}>\n      <div\n        style={{\n          background: RED,\n          color: CREAM,\n          padding: '3.6cqw 6cqw 4.4cqw',\n          display: 'flex',\n          flexDirection: 'column',\n          alignItems: 'center',\n          gap: '2.6cqw',\n          flex: 'none',\n        }}\n      >\n        <Micro style={{ fontSize: '2.6cqw', letterSpacing: '0.26em' }}>Grade A · Pasteurized · Homogenized</Micro>\n        <div style={{ display: 'flex', alignItems: 'center', gap: '3.5cqw' }}>\n          <RoundSeal\n            size=\"13cqw\"\n            legend=\"GRADE A · PASTEURIZED · \"\n            color={CREAM}\n            ring={false}\n            center={<span style={{ fontFamily: SERIF, fontSize: '6cqw', lineHeight: 1 }}>A</span>}\n          />\n          <Badge size={52} onBand />\n          <RoundSeal\n            size=\"13cqw\"\n            legend=\"FARMER OWNED · VERMONT · \"\n            color={CREAM}\n            ring={false}\n            center={<span style={{ fontSize: '2.2cqw', fontWeight: 800, letterSpacing: '0.08em' }}>CO-OP</span>}\n          />\n        </div>\n      </div>\n      <div style={{ flex: 1, minHeight: 0, display: 'flex', flexDirection: 'column', padding: '4cqw 6cqw 4.5cqw', gap: '2.4cqw' }}>\n        <div style={{ textAlign: 'center' }}>\n          <Pill color={ink} ink={onInk} size=\"2.9cqw\">\n            Vitamin D\n          </Pill>\n          <div\n            style={{\n              fontFamily: FONT,\n              fontWeight: 800,\n              fontSize: '19.5cqw',\n              lineHeight: 0.9,\n              letterSpacing: '-0.045em',\n              color: RED,\n              marginTop: '2.2cqw',\n            }}\n          >\n            Whole\n            <br />\n            Milk\n          </div>\n          <Micro style={{ fontSize: '2.7cqw', display: 'block', marginTop: '1.8cqw', letterSpacing: '0.24em' }}>3.25 % Milkfat · Ultra-pasteurized</Micro>\n        </div>\n        <div style={{ flex: 1, minHeight: 0, borderRadius: '3cqw', overflow: 'hidden', margin: '0.6cqw 0' }}>\n          <Photo src={asset('/art/milk-farm.webp')} position=\"50% 58%\" />\n        </div>\n        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-end', gap: '3cqw' }}>\n          <div>\n            <div style={{ fontWeight: 800, fontSize: '8.6cqw', letterSpacing: '-0.035em', lineHeight: 1 }}>HALF GALLON</div>\n            <div style={{ fontSize: '3.6cqw', fontWeight: 600, marginTop: '1.2cqw', letterSpacing: '0.02em' }}>(1.89 L) · 64 FL OZ</div>\n          </div>\n          <RoundSeal\n            size=\"17cqw\"\n            legend=\"FARMER OWNED · SINCE 1948 · \"\n            color={ink}\n            center={\n              <span style={{ fontSize: '3cqw', fontWeight: 800, letterSpacing: '0.02em' }}>\n                rBST\n                <br />\n                FREE*\n              </span>\n            }\n          />\n        </div>\n        <Micro style={{ fontSize: '2.4cqw', opacity: 0.72, textAlign: 'center' }}>Keep refrigerated · Sell by date on top</Micro>\n      </div>\n    </Face>\n  )\n}",
  "carton-art:CartonRoof": "/**\n * The front roof panel, the cap sitting in the middle of it: the sell-by\n * date and the plant code, jetted on above the cap in the dot-matrix the\n * filling line prints with, and the carton's name along the eave below it.\n */\nexport function CartonRoof({ material }: { material: string }) {\n  const { ink } = dairyInk(material)\n  return (\n    <Sheet tone={materialTone(material)} style={{ color: ink, flexDirection: 'column', justifyContent: 'space-between', padding: '3cqw 5cqw 3.2cqw' }}>\n      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>\n        <div>\n          <Micro style={{ fontSize: '2.4cqw', opacity: 0.72 }}>Sell by</Micro>\n          <JetPrint color={ink} size=\"4.8cqw\" style={{ marginTop: '0.6cqw' }}>\n            OCT 03 26\n          </JetPrint>\n        </div>\n        <JetPrint color={ink} size=\"3.4cqw\" style={{ textAlign: 'right' }}>\n          {'PLT 50-2117\\n04:12 A'}\n        </JetPrint>\n      </div>\n      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-end' }}>\n        <Micro style={{ fontSize: '2.4cqw' }}>Harlow Valley · Vitamin D Whole Milk</Micro>\n        <Micro style={{ fontSize: '2.4cqw', opacity: 0.72 }}>Twist cap to open</Micro>\n      </div>\n    </Sheet>\n  )\n}",
  "carton-art:CartonStory": "/** The left side: where the milk is from, and what the farmers promise. */\nexport function CartonStory({ material }: { material: string }) {\n  const { ink } = dairyInk(material)\n  return (\n    <Face material={material} style={{ gap: '2.6cqw' }}>\n      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'baseline' }}>\n        <Micro style={{ color: RED, fontSize: '2.8cqw' }}>Our farmers&apos; pledge</Micro>\n        <Micro style={{ fontSize: '2.8cqw', opacity: 0.72 }}>Harlow, Vermont</Micro>\n      </div>\n      <div style={{ fontFamily: SERIF, fontSize: '9cqw', lineHeight: 1.05, letterSpacing: '-0.015em' }}>\n        From 60 family farms, all within 100 miles of our creamery.\n      </div>\n      <p style={body('3.4cqw')}>\n        Every drop in this carton comes from cows raised on pasture by families we know by name. Our trucks\n        make the rounds each morning and the milk is bottled the same day, so it reaches your table the way\n        it left the farm.\n      </p>\n      <div style={{ flex: 1, minHeight: 0, borderRadius: '3cqw', overflow: 'hidden' }}>\n        {/* The herd, zoomed out of the same painting the front shows the glass in. */}\n        <Photo src={asset('/art/milk-farm.webp')} position=\"50% 50%\" style={{ transform: 'scale(1.75)', transformOrigin: '76% 47%' }} />\n      </div>\n      <ul style={{ margin: 0, padding: 0, listStyle: 'none', display: 'grid', gap: '1.6cqw', ...body('3.3cqw', { fontWeight: 600 }) }}>\n        <Tick color={RED}>No artificial growth hormones*</Tick>\n        <Tick color={RED}>Pasture-raised, Grade A</Tick>\n        <Tick color={RED}>Farmer owned since 1948</Tick>\n      </ul>\n      <p style={body('2.5cqw', { opacity: 0.8 })}>\n        *No significant difference has been shown between milk derived from rBST-treated and non-rBST-treated\n        cows.\n      </p>\n      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'baseline', gap: '2cqw' }}>\n        <Micro style={{ fontSize: '2.5cqw' }}>harlowvalleydairy.com</Micro>\n        <Micro style={{ fontSize: '2.5cqw', opacity: 0.72 }}>Questions? 1-800-555-0148</Micro>\n      </div>\n    </Face>\n  )\n}",
  "carton-art:CREAM": "const CREAM = '#fff8ea'",
  "carton-art:dairyInk": "/** Ink for the small print: the house navy on a light board, white ink on a dark one. */\nfunction dairyInk(material: string): { ink: string; onInk: string; dark: boolean } {\n  const dark = materialTone(material).text !== INK\n  return { ink: dark ? PAPER : NAVY, onInk: dark ? INK : CREAM, dark }\n}",
  "carton-art:Face": "/** A wall of the carton: the board as the container, the print laid out inside it. */\nfunction Face({ material, style, children }: { material: string; style?: CSSProperties; children: ReactNode }) {\n  return (\n    <Sheet\n      tone={materialTone(material)}\n      style={{ flexDirection: 'column', padding: '5cqw', gap: '2.4cqw', color: dairyInk(material).ink, ...style }}\n    >\n      {children}\n    </Sheet>\n  )\n}",
  "carton-art:MiniCarton": "/** One of the range on the back: a gable-top with the band colour a shelf sorts by. */\nfunction MiniCarton({ color, pct, label, ink }: { color: string; pct: string; label: string; ink: string }) {\n  return (\n    <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '1.6cqw', minWidth: 0 }}>\n      <svg viewBox=\"0 0 60 104\" style={{ width: '70%', display: 'block' }} aria-hidden>\n        <path d=\"M8 30L30 12l22 18v72H8z\" fill=\"#fbfaf5\" stroke={ink} strokeWidth={1.4} strokeLinejoin=\"round\" />\n        <path d=\"M8 30h44\" stroke={ink} strokeWidth={1} />\n        <rect x={26} y={7} width={8} height={6} rx={1} fill=\"#fbfaf5\" stroke={ink} strokeWidth={1.2} />\n        <rect x={8.7} y={30.7} width={42.6} height={17} fill={color} />\n        <text x={30} y={72} textAnchor=\"middle\" fontFamily={FONT} fontWeight={800} fontSize={20} fill={color} letterSpacing={-1}>\n          {pct}\n        </text>\n        <text x={30} y={86} textAnchor=\"middle\" fontFamily={FONT} fontWeight={700} fontSize={7} fill={ink} letterSpacing={1.4}>\n          MILK\n        </text>\n      </svg>\n      <Micro style={{ fontSize: '2.5cqw', textAlign: 'center', lineHeight: 1.2 }}>{label}</Micro>\n    </div>\n  )\n}",
  "carton-art:Mug": "/** A mug of cocoa, steaming - the back's serving suggestion. */\nfunction Mug({ ink }: { ink: string }) {\n  return (\n    <svg viewBox=\"0 0 80 90\" style={{ display: 'block', width: '100%', height: '100%' }} aria-hidden>\n      <g fill=\"none\" stroke={ink} strokeWidth={2.2} strokeLinecap=\"round\">\n        <path d=\"M30 6c-4 6 4 10 0 16\" opacity={0.55} />\n        <path d=\"M42 4c-4 6 4 10 0 16\" opacity={0.55} />\n        <path d=\"M54 8c-4 6 4 10 0 16\" opacity={0.55} />\n      </g>\n      <path d=\"M14 30h52v34a14 14 0 0 1-14 14H28a14 14 0 0 1-14-14z\" fill=\"#fbfaf5\" stroke={ink} strokeWidth={2.4} strokeLinejoin=\"round\" />\n      <path d=\"M66 38h6a8 8 0 0 1 0 16h-6\" fill=\"none\" stroke={ink} strokeWidth={2.4} />\n      <path d=\"M17 33h46v6H17z\" fill=\"#6b3a1e\" />\n      <g fill=\"#fffdf6\" stroke=\"#d8d2c4\" strokeWidth={0.8}>\n        <circle cx={30} cy={36} r={4.2} />\n        <circle cx={40} cy={35} r={4.6} />\n        <circle cx={50} cy={36.5} r={4} />\n      </g>\n      <rect x={20} y={48} width={40} height={18} rx={2} fill={RED} opacity={0.9} />\n      <text x={40} y={60} textAnchor=\"middle\" fontFamily={FONT} fontWeight={800} fontSize={8} fill={CREAM} letterSpacing={1}>\n        HARLOW\n      </text>\n    </svg>\n  )\n}",
  "carton-art:NAVY": "const NAVY = '#1d3557'",
  "carton-art:RED": "/** The dairy's inks. Red is the US whole-milk band; navy is the house colour. */\nconst RED = '#c2182f'",
  "carton-art:Tick": "/** A tick-list line: the pledges a carton makes on its side. */\nfunction Tick({ children, color }: { children: ReactNode; color: string }) {\n  return (\n    <li style={{ display: 'flex', gap: '2.2cqw', alignItems: 'baseline' }}>\n      <svg viewBox=\"0 0 20 20\" style={{ width: '3.6cqw', height: '3.6cqw', flex: 'none', transform: 'translateY(0.3cqw)' }} aria-hidden>\n        <circle cx={10} cy={10} r={9} fill={color} />\n        <path d=\"M5.5 10.5l3 3 6-7\" fill=\"none\" stroke={CREAM} strokeWidth={2.4} strokeLinecap=\"round\" strokeLinejoin=\"round\" />\n      </svg>\n      <span>{children}</span>\n    </li>\n  )\n}",
  "chroma-surface:ChromaSurface": "/**\n * Chroma-key fill for the \"mockup-able areas\" view: broadcast green with the\n * slot's name printed across it.\n *\n * Every region of a mockup gets one at once, which is the point - it is the\n * fastest way to see where your content lands and what stays 3D hardware. The\n * label sizes off the surface rather than the page (`cqw`/`cqh` against a size\n * container), so a spine strip and a billboard face both end up legible.\n */\nexport function ChromaSurface({ label }: { label: string }) {\n  return (\n    <div\n      style={{\n        width: '100%',\n        height: '100%',\n        background: '#00b140',\n        display: 'flex',\n        alignItems: 'center',\n        justifyContent: 'center',\n        containerType: 'size',\n        overflow: 'hidden',\n      }}\n    >\n      <span\n        style={{\n          fontFamily: 'ui-monospace, monospace',\n          fontWeight: 700,\n          fontSize: 'min(11cqw, 34cqh)',\n          color: '#063d1e',\n          letterSpacing: '0.05em',\n          whiteSpace: 'nowrap',\n        }}\n      >\n        {label}\n      </span>\n    </div>\n  )\n}",
  "device-apps:Kicker": "function Kicker({ children }: { children: ReactNode }) {\n  return (\n    <div style={{ fontSize: 10.5, fontWeight: 700, color: NEWS_RED, letterSpacing: '0.1em', textTransform: 'uppercase' }}>{children}</div>\n  )\n}",
  "device-apps:MOST_READ": "const MOST_READ = [\n  'Why the city’s rents fell for the first time in nine years',\n  'The quiet return of the neighbourhood bakery',\n  'Opinion: A tram is a promise kept, and that is rarer than it should be',\n  'Weekend weather: the last warm days of the year',\n]",
  "device-apps:NEWS_INK": "const NEWS_INK = '#161616'",
  "device-apps:NEWS_MUTED": "const NEWS_MUTED = '#5e5b55'",
  "device-apps:NEWS_PAPER": "const NEWS_PAPER = '#f7f5f0'",
  "device-apps:NEWS_RED": "const NEWS_RED = '#b3261e'",
  "device-apps:Newspaper": "/**\n * The morning paper on the Fold: masthead and section bar across both pages,\n * the lead story with its photograph on the left page, three shorter pieces\n * with thumbnails, the most-read list and the markets on the right. The two\n * columns leave a gutter down the middle for the hinge, so the crease falls\n * between the pages the way it does in a folded newspaper.\n */\nexport function Newspaper() {\n  return (\n    <div\n      style={{\n        width: '100%',\n        height: '100%',\n        boxSizing: 'border-box',\n        background: NEWS_PAPER,\n        color: NEWS_INK,\n        fontFamily: FONT,\n        display: 'flex',\n        flexDirection: 'column',\n        padding: '54px 28px 22px',\n        // The Fold draws One UI's bar over the top of the inner display; this\n        // clears the band it actually occupies rather than a number tuned to\n        // one variant. `0px` off a device, where this also renders.\n        paddingTop: 'calc(var(--mockup-safe-area-top, 0px) + 18px)',\n        overflow: 'hidden',\n        userSelect: 'none',\n      }}\n    >\n      <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: 10.5, letterSpacing: '0.06em', textTransform: 'uppercase', color: NEWS_MUTED }}>\n        <span>Tuesday, September 15, 2026 · Morning edition</span>\n        <span>Partly sunny · 68° / 54° · Sign in</span>\n      </div>\n      <div style={{ ...rule(2), borderBottom: `1px solid ${NEWS_INK}`, marginTop: 8, padding: '10px 0 9px', textAlign: 'center' }}>\n        <div style={{ fontFamily: SERIF, fontSize: 58, lineHeight: 1, letterSpacing: '-0.01em' }}>The Meridian</div>\n      </div>\n      <nav\n        style={{\n          display: 'flex',\n          justifyContent: 'space-between',\n          padding: '8px 2px',\n          borderBottom: `1px solid ${NEWS_INK}`,\n          fontSize: 11.5,\n          fontWeight: 600,\n          letterSpacing: '0.08em',\n          textTransform: 'uppercase',\n        }}\n      >\n        {['World', 'Politics', 'Business', 'Science', 'Culture', 'Sport', 'Opinion', 'Puzzles'].map((section) => (\n          <span key={section} style={section === 'World' ? { color: NEWS_RED } : undefined}>\n            {section}\n          </span>\n        ))}\n      </nav>\n\n      {/* One row, pinned to the page: the lead's body runs off the foot of the\n          page the way a jump story does, rather than pushing the row taller\n          than the screen and the markets strip off it. */}\n      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gridTemplateRows: 'minmax(0, 1fr)', columnGap: 46, flex: 1, minHeight: 0, paddingTop: 16 }}>\n        {/* the left page: the lead */}\n        <article style={{ minWidth: 0, minHeight: 0, overflow: 'hidden' }}>\n          <div style={{ height: 222, overflow: 'hidden' }}>\n            <Photo src={asset('/art/news-lead.webp')} position=\"50% 45%\" />\n          </div>\n          <div style={{ fontSize: 10.5, lineHeight: 1.35, color: NEWS_MUTED, marginTop: 6 }}>\n            The first eastbound tram crosses Founders Bridge at 6:12 a.m. Photograph: Ana Ferreira for The Meridian\n          </div>\n          <div style={{ marginTop: 14 }}>\n            <Kicker>Transit</Kicker>\n          </div>\n          <h1 style={{ fontFamily: SERIF, fontWeight: 400, fontSize: 33, lineHeight: 1.08, letterSpacing: '-0.012em', margin: '6px 0 10px', color: NEWS_INK }}>\n            City&rsquo;s first light-rail line opens to dawn crowds and a decade of promises\n          </h1>\n          <p style={{ fontFamily: SERIF, fontSize: 14.5, lineHeight: 1.4, color: '#33312c', margin: '0 0 9px' }}>\n            Twelve years after the referendum, the Green Line carried 41,000 riders on its first morning. The\n            second phase breaks ground in spring.\n          </p>\n          <div style={{ fontSize: 11, color: NEWS_MUTED, marginBottom: 10 }}>\n            By <strong style={{ color: NEWS_INK, fontWeight: 600 }}>Marcus Ellery</strong> · 7 min read\n          </div>\n          <div style={{ columnCount: 2, columnGap: 16, fontSize: 11.5, lineHeight: 1.5, textAlign: 'justify', hyphens: 'auto' }}>\n            <p style={{ margin: 0 }}>\n              <span style={{ fontFamily: SERIF, fontSize: 34, float: 'left', lineHeight: 0.8, paddingRight: 6, paddingTop: 4 }}>T</span>\n              he first eastbound tram left Founders Bridge at 6:12 a.m. with every seat taken and a small crowd\n              applauding from the platform, and by the time the morning rush had thinned the transit authority\n              was reporting ridership at roughly double its opening-day forecast.\n            </p>\n            <p style={{ margin: '8px 0 0' }}>\n              The 14-kilometre line, approved by voters in 2014 and delayed twice by funding disputes, links the\n              university district with the riverfront and the regional rail hub. Trains run every six minutes at\n              peak and every twelve off-peak, and the first month of fares has been waived.\n            </p>\n            <p style={{ margin: '8px 0 0' }}>\n              &ldquo;It is not a monument, it is a timetable,&rdquo; said transit director Hana Okafor, who rode\n              the first service. &ldquo;Judge it in a year, when it is just how people get to work.&rdquo; A second\n              phase north to the hospital campus is due to start construction in April.\n            </p>\n          </div>\n        </article>\n\n        {/* the right page: the shorts, the list, the markets */}\n        <aside style={{ minWidth: 0, minHeight: 0, display: 'flex', flexDirection: 'column' }}>\n          {SECOND.map((story) => (\n            <article\n              key={story.title}\n              style={{ display: 'grid', gridTemplateColumns: '1fr 120px', gap: 14, paddingBottom: 10, marginBottom: 10, borderBottom: '1px solid #d6d1c6' }}\n            >\n              <div style={{ minWidth: 0 }}>\n                <Kicker>{story.kicker}</Kicker>\n                <h2 style={{ fontFamily: SERIF, fontWeight: 400, fontSize: 18, lineHeight: 1.15, letterSpacing: '-0.01em', margin: '4px 0 5px', color: NEWS_INK }}>\n                  {story.title}\n                </h2>\n                <p style={{ margin: 0, fontSize: 11, lineHeight: 1.38, color: '#33312c' }}>{story.standfirst}</p>\n                <div style={{ fontSize: 10.5, color: NEWS_MUTED, marginTop: 5 }}>By {story.byline}</div>\n              </div>\n              <div style={{ height: 94, overflow: 'hidden' }}>\n                <Photo src={story.photo} position={story.position} />\n              </div>\n            </article>\n          ))}\n          <div>\n            <div style={{ ...rule(2), paddingTop: 8, fontSize: 11, fontWeight: 700, letterSpacing: '0.1em', textTransform: 'uppercase' }}>Most read</div>\n            <ol style={{ margin: '6px 0 0', padding: 0, listStyle: 'none', display: 'grid', gap: 5 }}>\n              {MOST_READ.map((item, i) => (\n                <li key={item} style={{ display: 'flex', gap: 10, fontSize: 12, lineHeight: 1.3 }}>\n                  <span style={{ fontFamily: SERIF, fontSize: 18, lineHeight: 1, color: NEWS_RED, flex: 'none', width: 14 }}>{i + 1}</span>\n                  <span style={{ fontFamily: SERIF }}>{item}</span>\n                </li>\n              ))}\n            </ol>\n          </div>\n          <div style={{ marginTop: 'auto', ...rule(1), paddingTop: 7, display: 'flex', justifyContent: 'space-between', fontSize: 10.5, letterSpacing: '0.02em' }}>\n            <span>\n              S&amp;P 500 <strong style={{ color: '#1a7f4b' }}>+0.4%</strong>\n            </span>\n            <span>\n              Nasdaq <strong style={{ color: '#1a7f4b' }}>+0.7%</strong>\n            </span>\n            <span>10-yr 4.02%</span>\n            <span>EUR/USD 1.09</span>\n            <span>\n              Brent <strong style={{ color: NEWS_RED }}>−1.1%</strong>\n            </span>\n          </div>\n        </aside>\n      </div>\n    </div>\n  )\n}",
  "device-apps:rule": "/** A hairline in the paper's ink, at the weights a broadsheet uses. */\nconst rule = (weight = 1): CSSProperties => ({ borderTop: `${weight}px solid ${NEWS_INK}` })",
  "device-apps:SECOND": "const SECOND: Story[] = [\n  {\n    kicker: 'Environment',\n    title: 'Volunteers return four hundred rescued turtles to the surf',\n    standfirst: 'After a cold snap stranded them along the cape, the last of the rehabilitated ridleys went back into the Atlantic at first light.',\n    byline: 'Priya Desai',\n    photo: asset('/art/news-turtle.webp'),\n    position: '50% 60%',\n  },\n  {\n    kicker: 'Culture',\n    title: 'After thirty years, the Aldous Quartet plays its last residency',\n    standfirst: 'The ensemble that turned a shipyard hall into a concert venue bows out with the complete Beethoven cycle.',\n    byline: 'Tomas Brandt',\n    photo: asset('/art/news-quartet.webp'),\n  },\n  {\n    kicker: 'Sport',\n    title: 'Breakaway holds on the final climb as Marchetti takes the stage',\n    standfirst: 'The 24-year-old survived a late chase to win alone on the Col de Vars and move into third overall.',\n    byline: 'Leila Haddad',\n    photo: asset('/art/news-cycling.webp'),\n  },\n]",
  "device-apps:SITE_ACCENT": "const SITE_ACCENT = '#e1341e'",
  "device-apps:SITE_INK": "const SITE_INK = '#141414'",
  "device-apps:SITE_MUTED": "const SITE_MUTED = '#6b6963'",
  "device-apps:SITE_PAPER": "const SITE_PAPER = '#f4f2ec'",
  "device-apps:Story": "interface Story {\n  kicker: string\n  title: string\n  standfirst: string\n  byline: string\n  photo: string\n  position?: string\n}",
  "device-apps:SwissSite": "/**\n * A design studio's website: a strict grid, one typeface set tight, one\n * accent, and the studio's generative pieces doing the work photography\n * would. The hero pattern is live - it reseeds itself - because this is a\n * screen and the page is here to say so.\n */\nexport function SwissSite() {\n  const cards: [typeof damier, string, string, string, string, string][] = [\n    [damier, 'kunsthalle', 'Kunsthalle Basel', 'Identity system · 2026', '#e6f0ee', '#0f8b8d'],\n    [ortho, 'meridian', 'Meridian Transit', 'Wayfinding · 2025', '#f1e6d8', '#ff6a1a'],\n    [halftone, 'niggli', 'Verlag Niggli', 'Editorial design · 2025', '#e9e4f2', '#5b3fa0'],\n  ]\n  const link: CSSProperties = { fontSize: 15, fontWeight: 600, letterSpacing: '-0.01em' }\n  return (\n    <div\n      style={{\n        width: '100%',\n        height: '100%',\n        boxSizing: 'border-box',\n        background: SITE_PAPER,\n        color: SITE_INK,\n        fontFamily: FONT,\n        letterSpacing: '-0.015em',\n        display: 'flex',\n        flexDirection: 'column',\n        overflow: 'hidden',\n        userSelect: 'none',\n      }}\n    >\n      <header\n        style={{\n          display: 'flex',\n          alignItems: 'center',\n          justifyContent: 'space-between',\n          padding: '22px 48px',\n          borderBottom: `1px solid ${SITE_INK}`,\n        }}\n      >\n        <div style={{ display: 'flex', alignItems: 'center', gap: 12, fontWeight: 700, fontSize: 19, letterSpacing: '-0.035em' }}>\n          <span style={{ width: 14, height: 14, background: SITE_ACCENT, display: 'inline-block' }} />\n          Raster Studio\n        </div>\n        <nav style={{ display: 'flex', gap: 34, fontSize: 15, fontWeight: 500 }}>\n          <span style={{ borderBottom: `2px solid ${SITE_INK}`, paddingBottom: 2 }}>Work</span>\n          <span>Studio</span>\n          <span>Journal</span>\n          <span>Contact</span>\n        </nav>\n        <span\n          style={{\n            background: SITE_INK,\n            color: SITE_PAPER,\n            fontSize: 14,\n            fontWeight: 600,\n            padding: '9px 16px',\n            borderRadius: 999,\n          }}\n        >\n          Start a project →\n        </span>\n      </header>\n\n      <section style={{ display: 'grid', gridTemplateColumns: '7fr 5fr', gap: 48, padding: '52px 48px 40px' }}>\n        <div style={{ display: 'flex', flexDirection: 'column' }}>\n          <div style={{ display: 'flex', gap: 14, alignItems: 'baseline', fontSize: 13, fontWeight: 600, letterSpacing: '0.12em', textTransform: 'uppercase' }}>\n            <span style={{ color: SITE_ACCENT }}>01</span>\n            <span style={{ color: SITE_MUTED }}>Design studio · Zürich — Lisbon</span>\n          </div>\n          <h1 style={{ margin: '22px 0 24px', fontSize: 76, lineHeight: 0.97, fontWeight: 700, letterSpacing: '-0.045em', color: SITE_INK }}>\n            Systems that make good work inevitable.\n          </h1>\n          <p style={{ margin: 0, maxWidth: 540, fontSize: 19, lineHeight: 1.45, color: '#3a3833' }}>\n            We design identities, interfaces and the grids underneath them, for teams who would rather ship one\n            coherent thing than a hundred clever ones.\n          </p>\n          <div style={{ marginTop: 'auto', display: 'flex', gap: 28, paddingTop: 24 }}>\n            <span style={link}>Selected work →</span>\n            <span style={{ ...link, color: SITE_MUTED }}>How we work →</span>\n          </div>\n        </div>\n        <div style={{ position: 'relative', borderRadius: 6, overflow: 'hidden', background: SITE_INK, minHeight: 300 }}>\n          <div style={{ position: 'absolute', inset: 0 }}>\n            <Pattern pattern={gyre} live palette={[SITE_INK, SITE_PAPER, SITE_ACCENT]} grid=\"6x9\" />\n          </div>\n          <span\n            style={{\n              position: 'absolute',\n              left: 16,\n              bottom: 14,\n              color: SITE_PAPER,\n              fontSize: 12,\n              fontWeight: 600,\n              letterSpacing: '0.12em',\n              textTransform: 'uppercase',\n              opacity: 0.85,\n            }}\n          >\n            Fig. 01 — Rotation study\n          </span>\n        </div>\n      </section>\n\n      <section style={{ flex: 1, minHeight: 0, display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: 24, padding: '0 48px' }}>\n        {cards.map(([pattern, seed, title, meta, ground, accent]) => (\n          <article key={seed} style={{ display: 'flex', flexDirection: 'column', gap: 12, minHeight: 0 }}>\n            <div style={{ flex: 1, minHeight: 0, borderRadius: 6, overflow: 'hidden', background: ground }}>\n              <Pattern pattern={pattern} seed={`raster-${seed}`} palette={[ground, SITE_INK, accent]} grid=\"4x6\" />\n            </div>\n            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'baseline', fontSize: 14 }}>\n              <strong style={{ fontWeight: 600 }}>{title}</strong>\n              <span style={{ color: SITE_MUTED }}>{meta}</span>\n            </div>\n          </article>\n        ))}\n      </section>\n\n      <footer style={{ display: 'flex', justifyContent: 'space-between', padding: '22px 48px 24px', fontSize: 13, color: SITE_MUTED }}>\n        <span>© 2026 Raster Studio · Zürich — Lisbon</span>\n        <span>Instagram · Are.na · Newsletter</span>\n      </footer>\n    </div>\n  )\n}",
  "device-apps:WatchFace": "/**\n * A watch face for a round display: activity rings around the rim, the time\n * dead centre, the date above it and three complications below. Everything\n * sits inside the inscribed circle - a 240 px dial has no corners, so nothing\n * is set where a corner would be. Measurements are in `cqw` against the dial.\n */\nexport function WatchFace() {\n  const rings = [\n    { r: 44, pct: 0.72, color: '#3ddc84' },\n    { r: 39, pct: 0.46, color: '#5ec8ff' },\n    { r: 34, pct: 0.88, color: '#ff6b8b' },\n  ]\n  const stat = (value: string, label: string, color: string) => (\n    <div key={label} style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', lineHeight: 1 }}>\n      <span style={{ fontSize: '6cqw', fontWeight: 700, color, letterSpacing: '-0.02em' }}>{value}</span>\n      <span style={{ fontSize: '3.2cqw', fontWeight: 600, letterSpacing: '0.1em', opacity: 0.6, marginTop: '1.4cqw' }}>{label}</span>\n    </div>\n  )\n  return (\n    <div\n      style={{\n        width: '100%',\n        height: '100%',\n        containerType: 'size',\n        position: 'relative',\n        background: '#000000',\n        color: '#ffffff',\n        fontFamily: FONT,\n        borderRadius: '50%',\n        overflow: 'hidden',\n        userSelect: 'none',\n      }}\n    >\n      <style>{`@keyframes watch-ring-in { from { stroke-dashoffset: var(--c); } }`}</style>\n      <svg viewBox=\"0 0 100 100\" style={{ position: 'absolute', inset: 0, width: '100%', height: '100%', transform: 'rotate(-90deg)' }} aria-hidden>\n        {rings.map(({ r, pct, color }) => {\n          const c = 2 * Math.PI * r\n          return (\n            <g key={r}>\n              <circle cx={50} cy={50} r={r} fill=\"none\" stroke={color} strokeOpacity={0.2} strokeWidth={3.6} />\n              <circle\n                cx={50}\n                cy={50}\n                r={r}\n                fill=\"none\"\n                stroke={color}\n                strokeWidth={3.6}\n                strokeLinecap=\"round\"\n                strokeDasharray={c}\n                strokeDashoffset={c * (1 - pct)}\n                style={{ ['--c' as string]: c, animation: 'watch-ring-in 1.4s cubic-bezier(0.2, 0.7, 0.2, 1) both' }}\n              />\n            </g>\n          )\n        })}\n      </svg>\n      <div\n        style={{\n          position: 'absolute',\n          inset: 0,\n          display: 'flex',\n          flexDirection: 'column',\n          alignItems: 'center',\n          justifyContent: 'center',\n          textAlign: 'center',\n        }}\n      >\n        <span style={{ fontSize: '4.4cqw', fontWeight: 600, letterSpacing: '0.18em', opacity: 0.65 }}>MON 14</span>\n        <span style={{ fontSize: '21cqw', fontWeight: 800, letterSpacing: '-0.045em', lineHeight: 0.95, marginTop: '1cqw' }}>9:41</span>\n        <div style={{ display: 'flex', gap: '6cqw', marginTop: '4.5cqw' }}>\n          {stat('72', 'BPM', '#ff6b8b')}\n          {stat('6,842', 'STEPS', '#3ddc84')}\n          {stat('68°', 'SUNNY', '#5ec8ff')}\n        </div>\n      </div>\n    </div>\n  )\n}",
  "label-art:Ean13": "/**\n * A real, scannable EAN-13 - the symbol on the back of every book, where the\n * first three digits are the `978`/`979` Bookland prefix and the rest is the\n * ISBN without its own check digit.\n *\n * Same construction as `UpcA` above: guards at 101, a 01010 through the\n * middle, and the human-readable digits under the bars - except that the\n * leading digit sits outside the symbol in the left quiet zone, because it\n * has no bars of its own.\n */\nexport function Ean13({ digits, color, style }: { digits: string; color: string; style?: CSSProperties }) {\n  const code = digits.slice(0, 12) + eanCheck(digits.slice(0, 12))\n  const parity = PARITY[Number(code[0])]!\n  let bits = '101'\n  for (let i = 1; i < 7; i++) bits += (parity[i - 1] === 'L' ? L : G)[Number(code[i])]\n  bits += '01010'\n  for (let i = 7; i < 13; i++) bits += R[Number(code[i])]\n  bits += '101'\n  // Eleven modules of quiet zone on the left, where the lead digit is set.\n  const X0 = 11\n  const guard = (i: number) => i < 3 || (i >= 45 && i < 50) || i >= 92\n  const bars: ReactNode[] = []\n  for (let i = 0; i < bits.length; ) {\n    if (bits[i] === '0') {\n      i++\n      continue\n    }\n    let j = i\n    while (j < bits.length && bits[j] === '1') j++\n    bars.push(<rect key={i} x={X0 + i} y={0} width={j - i} height={guard(i) ? 72 : 66} fill={color} />)\n    i = j\n  }\n  const digit = (d: string, x: number, key: string) => (\n    <text key={key} x={x} y={78} textAnchor=\"middle\" fontSize={9} fontFamily={FONT} fill={color}>\n      {d}\n    </text>\n  )\n  return (\n    <svg viewBox=\"0 0 120 82\" style={{ display: 'block', ...style }} aria-hidden>\n      {bars}\n      {digit(code[0]!, 5, 'lead')}\n      {[...code.slice(1, 7)].map((d, i) => digit(d, X0 + 3 + 7 * i + 3.5, `l${i}`))}\n      {[...code.slice(7)].map((d, i) => digit(d, X0 + 50 + 7 * i + 3.5, `r${i}`))}\n    </svg>\n  )\n}",
  "label-art:eanCheck": "/** The check digit for the first twelve digits of an EAN-13. */\nfunction eanCheck(twelve: string): number {\n  let sum = 0\n  for (let i = 0; i < 12; i++) sum += Number(twelve[i]) * (i % 2 === 0 ? 1 : 3)\n  return (10 - (sum % 10)) % 10\n}",
  "label-art:G": "/** G-codes: the R-codes read backwards. EAN-13's left half mixes L and G. */\nconst G = R.map((bits) => [...bits].reverse().join(''))",
  "label-art:JetPrint": "/**\n * The ink-jet: a best-before or a lot code sprayed on by the filling line,\n * in the dot-matrix mono that sits on top of the print job rather than in it.\n */\nexport function JetPrint({ children, color, size, style }: { children: ReactNode; color: string; size: string; style?: CSSProperties }) {\n  return (\n    <div\n      style={{\n        fontFamily: MONO,\n        fontSize: size,\n        fontWeight: 500,\n        letterSpacing: '0.12em',\n        lineHeight: 1.3,\n        whiteSpace: 'pre-line',\n        color,\n        opacity: 0.86,\n        ...style,\n      }}\n    >\n      {children}\n    </div>\n  )\n}",
  "label-art:L": "const L = ['0001101', '0011001', '0010011', '0111101', '0100011', '0110001', '0101111', '0111011', '0110111', '0001011']",
  "label-art:MONO": "/** The filling line's ink-jet: the one face of a package that is not typeset. */\nexport const MONO = 'var(--font-jetbrains-mono), \"JetBrains Mono\", ui-monospace, Menlo, Consolas, monospace'",
  "label-art:NutrientRow": "export interface NutrientRow {\n  label: string\n  amount: string\n  /** Percent daily value; omitted where the FDA format prints none (trans fat, total sugars). */\n  dv?: string\n  /** Indented under its parent: saturated fat under total fat, added sugars two deep. */\n  indent?: 0 | 1 | 2\n  /** The bold entries: the main nutrients. Sub-rows are set regular. */\n  bold?: boolean\n}",
  "label-art:NutritionFacts": "/**\n * The FDA's 2020 Nutrition Facts panel, rule for rule: the heavy title, the\n * servings line, the 7pt bar over \"Amount per serving\", calories set at\n * three times the body, the % Daily Value column, the thick bar before the\n * vitamins and the footnote. What a US package prints is regulated down to\n * the rule weights, which is what makes it instantly recognisable - and why\n * an approximation reads as a table, not as a label.\n */\nexport function NutritionFacts({\n  servings,\n  servingSize,\n  calories,\n  rows,\n  micros,\n  color = '#111111',\n  background = '#ffffff',\n  fontSize,\n  compact,\n  style,\n}: NutritionFactsProps) {\n  const line = (weight: string): CSSProperties => ({ borderTop: `${weight} solid ${color}`, flex: 'none' })\n  const row = (r: NutrientRow, i: number, last: boolean) => (\n    <div\n      key={`${r.label}-${i}`}\n      style={{\n        display: 'flex',\n        justifyContent: 'space-between',\n        gap: '0.6em',\n        padding: compact ? '0.16em 0' : '0.22em 0',\n        paddingLeft: `${(r.indent ?? 0) * 1.1}em`,\n        borderBottom: last ? 'none' : `0.07em solid ${color}`,\n        lineHeight: 1.15,\n      }}\n    >\n      <span>\n        <span style={{ fontWeight: r.bold ? 700 : 400 }}>{r.label}</span> {r.amount}\n      </span>\n      {r.dv != null && <span style={{ fontWeight: 700, whiteSpace: 'nowrap' }}>{r.dv}</span>}\n    </div>\n  )\n  return (\n    <div\n      style={{\n        boxSizing: 'border-box',\n        border: `0.12em solid ${color}`,\n        padding: '0.35em 0.45em 0.45em',\n        background,\n        color,\n        fontFamily: FONT,\n        fontSize,\n        lineHeight: 1.2,\n        display: 'flex',\n        flexDirection: 'column',\n        textAlign: 'left',\n        ...style,\n      }}\n    >\n      <div style={{ fontWeight: 900, fontSize: '2.15em', lineHeight: 0.95, letterSpacing: '-0.03em' }}>\n        Nutrition Facts\n      </div>\n      <div style={{ padding: '0.35em 0 0.2em', borderBottom: `0.07em solid ${color}` }}>{servings} servings per container</div>\n      <div\n        style={{\n          display: 'flex',\n          justifyContent: 'space-between',\n          gap: '0.6em',\n          fontWeight: 700,\n          fontSize: '1.15em',\n          padding: '0.25em 0',\n        }}\n      >\n        <span>Serving size</span>\n        <span style={{ textAlign: 'right' }}>{servingSize}</span>\n      </div>\n      <div style={line('0.7em')} />\n      <div style={{ fontWeight: 700, fontSize: '0.82em', paddingTop: '0.3em' }}>Amount per serving</div>\n      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-end', gap: '0.6em' }}>\n        <span style={{ fontWeight: 900, fontSize: '1.9em', lineHeight: 1 }}>Calories</span>\n        <span style={{ fontWeight: 900, fontSize: '3em', lineHeight: 0.85 }}>{calories}</span>\n      </div>\n      <div style={{ ...line('0.35em'), marginTop: '0.3em' }} />\n      <div\n        style={{\n          textAlign: 'right',\n          fontWeight: 700,\n          fontSize: '0.9em',\n          padding: '0.25em 0',\n          borderBottom: `0.07em solid ${color}`,\n        }}\n      >\n        % Daily Value*\n      </div>\n      {rows.map((r, i) => row(r, i, i === rows.length - 1))}\n      <div style={line('0.7em')} />\n      {micros.map((r, i) => row(r, i, i === micros.length - 1))}\n      <div style={{ ...line('0.35em'), marginTop: '0.1em' }} />\n      <p style={{ margin: 0, paddingTop: '0.3em', fontSize: '0.78em', lineHeight: 1.25 }}>\n        * The % Daily Value (DV) tells you how much a nutrient in a serving of food contributes to a daily\n        diet. 2,000 calories a day is used for general nutrition advice.\n      </p>\n    </div>\n  )\n}",
  "label-art:NutritionFactsProps": "export interface NutritionFactsProps {\n  servings: string\n  servingSize: string\n  calories: string\n  rows: NutrientRow[]\n  /** The vitamin and mineral block under the thick rule. */\n  micros: NutrientRow[]\n  /** Ink and the label ground: a nutrition panel is black on white wherever the package is printed. */\n  color?: string\n  background?: string\n  /** Base size, in the caller's units - every measurement inside is relative to it. */\n  fontSize: string\n  /** Shorter footnote and tighter leading for a narrow side panel. */\n  compact?: boolean\n  style?: CSSProperties\n}",
  "label-art:PARITY": "/**\n * Which of the left six digits are set in G rather than L. EAN-13 has no\n * module of its own for the first digit - it is carried entirely by this\n * parity pattern, which is the trick that fits thirteen digits into twelve\n * digits' worth of bars.\n */\nconst PARITY = [\n  'LLLLLL', 'LLGLGG', 'LLGGLG', 'LLGGGL', 'LGLLGG',\n  'LGGLLG', 'LGGGLL', 'LGLGLG', 'LGLGGL', 'LGGLGL',\n]",
  "label-art:Photo": "/**\n * A picture on the pack - the generated photograph or illustration a real\n * package prints where a poster would have a pattern - full-bleed in its box\n * unless told otherwise. `position` crops it (`object-position`), which is\n * how the carton's story side shows the herd from the same painting the\n * front shows the glass in.\n */\nexport function Photo({ src, position = '50% 50%', fit = 'cover', style }: { src: string; position?: string; fit?: 'cover' | 'contain'; style?: CSSProperties }) {\n  return (\n    // eslint-disable-next-line @next/next/no-img-element\n    <img\n      src={src}\n      alt=\"\"\n      draggable={false}\n      style={{ display: 'block', width: '100%', height: '100%', objectFit: fit, objectPosition: position, ...style }}\n    />\n  )\n}",
  "label-art:Pill": "/** A claim in a pill: \"VITAMIN D\", \"FAMILY SIZE\" - a shape a shelf reads from ten feet. */\nexport function Pill({\n  children,\n  color,\n  ink,\n  size,\n  style,\n}: {\n  children: ReactNode\n  /** Fill. */\n  color: string\n  /** Type colour on the fill. */\n  ink: string\n  size: string\n  style?: CSSProperties\n}) {\n  return (\n    <span\n      style={{\n        display: 'inline-block',\n        background: color,\n        color: ink,\n        fontFamily: FONT,\n        fontSize: size,\n        fontWeight: 800,\n        letterSpacing: '0.14em',\n        textTransform: 'uppercase',\n        lineHeight: 1,\n        padding: '0.45em 0.9em 0.4em',\n        borderRadius: '2em',\n        whiteSpace: 'nowrap',\n        ...style,\n      }}\n    >\n      {children}\n    </span>\n  )\n}",
  "label-art:R": "const R = ['1110010', '1100110', '1101100', '1000010', '1011100', '1001110', '1010000', '1000100', '1001000', '1110100']",
  "label-art:RecycleMark": "/** The chasing arrows: the \"please recycle\" every carton and box carries. */\nexport function RecycleMark({ color, size, label }: { color: string; size: string; label?: ReactNode }) {\n  return (\n    <div style={{ display: 'flex', alignItems: 'center', gap: '0.5em', color, fontFamily: FONT }}>\n      <svg viewBox=\"0 0 48 48\" style={{ width: size, height: size, display: 'block', flex: 'none' }} aria-hidden>\n        <g fill=\"none\" stroke={color} strokeWidth={4} strokeLinecap=\"round\" strokeLinejoin=\"round\">\n          <path d=\"M18 14 24 4l6 10\" />\n          <path d=\"M30 14 36 24\" />\n          <path d=\"M9 30 3 20l11-2\" />\n          <path d=\"M9 30l6 10h12\" />\n          <path d=\"M39 30l6-10-11-2\" />\n          <path d=\"M39 30l-6 10\" />\n        </g>\n        <g fill={color}>\n          <path d=\"M27 40l6-4-1 8z\" />\n          <path d=\"M14 18l-6 3 6 3z\" transform=\"rotate(-30 14 21)\" />\n          <path d=\"M34 18l6 3-6 3z\" transform=\"rotate(30 34 21)\" />\n        </g>\n      </svg>\n      {label && <span style={{ fontSize: '0.8em', lineHeight: 1.1 }}>{label}</span>}\n    </div>\n  )\n}",
  "label-art:RoundSeal": "/**\n * A round seal with its legend running round the rim and a word or a glyph\n * in the middle: the \"Grade A\" on a carton, the \"whole grain\" on a cereal\n * box, the claim stamps a package wears like badges. `size` is the diameter\n * in the caller's units.\n */\nexport function RoundSeal({\n  size,\n  legend,\n  center,\n  color,\n  fill = 'transparent',\n  ring = true,\n  style,\n}: {\n  size: string\n  legend: string\n  center: ReactNode\n  color: string\n  fill?: string\n  ring?: boolean\n  style?: CSSProperties\n}) {\n  // Ids are document-global and every seal on the stage shares one document.\n  const rim = useId()\n  return (\n    <div style={{ position: 'relative', width: size, height: size, flex: 'none', ...style }}>\n      <svg viewBox=\"0 0 100 100\" style={{ position: 'absolute', inset: 0, width: '100%', height: '100%' }} aria-hidden>\n        <circle cx={50} cy={50} r={48} fill={fill} stroke={color} strokeWidth={2.4} />\n        {ring && <circle cx={50} cy={50} r={33} fill=\"none\" stroke={color} strokeWidth={1.2} />}\n        <defs>\n          <path id={rim} d=\"M50 50 m-40.5 0 a40.5 40.5 0 1 1 81 0 a40.5 40.5 0 1 1 -81 0\" />\n        </defs>\n        <text fontFamily={FONT} fontSize={8.6} fontWeight={700} letterSpacing={1.4} fill={color}>\n          <textPath href={`#${rim}`} startOffset=\"0\">\n            {legend}\n          </textPath>\n        </text>\n      </svg>\n      <div\n        style={{\n          position: 'absolute',\n          inset: '24%',\n          display: 'flex',\n          alignItems: 'center',\n          justifyContent: 'center',\n          textAlign: 'center',\n          color,\n          fontFamily: FONT,\n          lineHeight: 0.95,\n        }}\n      >\n        {center}\n      </div>\n    </div>\n  )\n}",
  "label-art:SERIF": "/** A dairy or a mill sets its name in something with serifs; Inter is for the small print. */\nexport const SERIF = 'Georgia, \"Iowan Old Style\", \"Palatino Linotype\", \"Book Antiqua\", \"Times New Roman\", serif'",
  "label-art:UpcA": "/**\n * A real, scannable UPC-A - the symbol on every US grocery package. Left\n * guard, six L-coded digits, the centre guard, six R-coded digits, right\n * guard; the number system digit set small to the left and the check digit\n * small to the right, both with their bars running the full height the way\n * a printer's plate has them. The article number is fictional; the check\n * digit is not.\n */\nexport function UpcA({ digits, color, style }: { digits: string; color: string; style?: CSSProperties }) {\n  const code = digits.slice(0, 11) + upcCheck(digits.slice(0, 11))\n  let bits = '101'\n  for (let i = 0; i < 6; i++) bits += L[Number(code[i])]\n  bits += '01010'\n  for (let i = 6; i < 12; i++) bits += R[Number(code[i])]\n  bits += '101'\n  // Nine modules of quiet zone each side. The two outer digits' bars are as\n  // tall as the guards, so the human-readable digits fit under the middle ten.\n  const X0 = 9\n  const tall = (i: number) => i < 10 || (i >= 45 && i < 50) || i >= 85\n  const bars: ReactNode[] = []\n  for (let i = 0; i < bits.length; ) {\n    if (bits[i] === '0') {\n      i++\n      continue\n    }\n    let j = i\n    while (j < bits.length && bits[j] === '1') j++\n    bars.push(<rect key={i} x={X0 + i} y={0} width={j - i} height={tall(i) ? 66 : 60} fill={color} />)\n    i = j\n  }\n  const digit = (d: string, x: number, key: string, size = 9) => (\n    <text key={key} x={x} y={74} textAnchor=\"middle\" fontSize={size} fontFamily={FONT} fill={color}>\n      {d}\n    </text>\n  )\n  return (\n    <svg viewBox=\"0 0 113 78\" style={{ display: 'block', ...style }} aria-hidden>\n      {bars}\n      {digit(code[0]!, 4, 'ns', 7)}\n      {[...code.slice(1, 6)].map((d, i) => digit(d, X0 + 10 + 7 * i + 3.5, `l${i}`))}\n      {[...code.slice(6, 11)].map((d, i) => digit(d, X0 + 50 + 7 * i + 3.5, `r${i}`))}\n      {digit(code[11]!, 109, 'ck', 7)}\n    </svg>\n  )\n}",
  "label-art:upcCheck": "/** The check digit for the first eleven digits of a UPC-A. */\nfunction upcCheck(eleven: string): number {\n  let sum = 0\n  for (let i = 0; i < 11; i++) sum += Number(eleven[i]) * (i % 2 === 0 ? 3 : 1)\n  return (10 - (sum % 10)) % 10\n}",
  "live-counter:LiveCounter": "/**\n * A screen whose React state keeps ticking on the glass: `useState` +\n * `useEffect` running inside the 3D mockup, re-rendering every second like it\n * would anywhere else in the page.\n */\nexport function LiveCounter() {\n  const [seconds, setSeconds] = useState(0)\n\n  useEffect(() => {\n    const timer = setInterval(() => setSeconds((s) => s + 1), 1000)\n    return () => clearInterval(timer)\n  }, [])\n\n  return (\n    <div className=\"screen live\">\n      <div className=\"live-body\">\n        <p className=\"live-label\">seconds on screen</p>\n        <p className=\"live-count\" key={seconds}>\n          {seconds}\n        </p>\n        <div className=\"live-pulse\" aria-hidden>\n          <span />\n          <span />\n          <span />\n        </div>\n      </div>\n\n      <p className=\"live-footnote\">React state, running on a 3D screen.</p>\n      <div className=\"screen-homebar\" aria-hidden />\n    </div>\n  )\n}",
  "package-art:BagBack": "/** The back: what the shop prints on the other side of the bag. */\nexport function BagBack({ material }: { material: string }) {\n  const { ink, accent } = shop(material)\n  const t = materialTone(material)\n  return (\n    <Sheet tone={t} style={{ flexDirection: 'column', alignItems: 'center', justifyContent: 'center', padding: '16cqw 11cqw 9cqw', color: ink, textAlign: 'center', gap: '5cqw' }}>\n      <div style={{ fontFamily: SERIF, fontStyle: 'italic', fontSize: '8.4cqw', lineHeight: 1.2 }}>\n        Grown slow.\n        <br />\n        Cut this morning.\n        <br />\n        Wrapped with care.\n      </div>\n      <Micro style={{ fontSize: '2.9cqw', color: accent, letterSpacing: '0.3em' }}>Est. 2016</Micro>\n      <div style={{ flex: 1 }} />\n      <Bunch color={ink} style={{ width: '30cqw', height: 'auto', opacity: 0.9 }} />\n    </Sheet>\n  )\n}",
  "package-art:BagFront": "/** The front: the bunch, the name in serifs, the shop's address along the foot. */\nexport function BagFront({ material }: { material: string }) {\n  const { ink, accent } = shop(material)\n  const t = materialTone(material)\n  return (\n    <Sheet tone={t} style={{ flexDirection: 'column', alignItems: 'center', padding: '12cqw 9cqw 6.5cqw', color: ink, textAlign: 'center' }}>\n      <Bunch color={ink} style={{ width: '46cqw', height: 'auto', flex: 'none' }} />\n      <div style={{ fontFamily: SERIF, fontSize: '13.5cqw', lineHeight: 0.98, letterSpacing: '-0.02em', marginTop: '3cqw' }}>\n        Marigold\n        <br />\n        <span style={{ fontStyle: 'italic', color: accent }}>&amp;</span> Moss\n      </div>\n      <Micro style={{ fontSize: '2.8cqw', marginTop: '3.6cqw', letterSpacing: '0.3em' }}>Flowers · Plants · Workshops</Micro>\n      <div style={{ flex: 1, minHeight: '5cqw' }} />\n      <div style={{ display: 'grid', gap: '2cqw' }}>\n        <Micro style={{ fontSize: '2.7cqw' }}>34 Elm Street · Northampton, Mass.</Micro>\n        <Micro style={{ fontSize: '2.7cqw', opacity: 0.72 }}>marigoldandmoss.com · Tue–Sun 9–6</Micro>\n        <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', gap: '1.8cqw', marginTop: '1.2cqw' }}>\n          <RecycleMark color={ink} size=\"4.4cqw\" />\n          <Micro style={{ fontSize: '2.3cqw', opacity: 0.72 }}>Unbleached kraft · Please reuse me</Micro>\n        </div>\n      </div>\n    </Sheet>\n  )\n}",
  "package-art:BoxFace": "/** A panel of the box: the board as the container, the print laid out inside it. */\nfunction BoxFace({ material, style, children }: { material: string; style?: CSSProperties; children: ReactNode }) {\n  return (\n    <Sheet\n      tone={materialTone(material)}\n      style={{ flexDirection: 'column', padding: '4.5cqw', gap: '2cqw', color: mill(material).ink, ...style }}\n    >\n      {children}\n    </Sheet>\n  )\n}",
  "package-art:BrandTab": "/** The brand tab: the mill's name on a green lozenge, the ear beside it. `size` is the type size in cqw. */\nfunction BrandTab({ p, size }: { p: Mill; size: number }) {\n  return (\n    <div\n      style={{\n        display: 'inline-flex',\n        alignItems: 'center',\n        gap: `${size * 0.6}cqw`,\n        background: p.green,\n        color: '#fff4dc',\n        borderRadius: `${size * 0.6}cqw`,\n        padding: `${size * 0.5}cqw ${size * 0.95}cqw ${size * 0.5}cqw ${size * 0.75}cqw`,\n        flex: 'none',\n        alignSelf: 'flex-start',\n      }}\n    >\n      <Wheat color={p.honey} style={{ height: `${size * 1.55}cqw`, width: 'auto' }} />\n      <span style={{ fontFamily: FONT, fontWeight: 800, letterSpacing: '0.16em', fontSize: `${size}cqw`, lineHeight: 1, whiteSpace: 'nowrap' }}>\n        RIDGEWAY MILLS\n      </span>\n    </div>\n  )\n}",
  "package-art:Bunch": "/**\n * The florist's mark: a loose bunch drawn in one line - a poppy, a stem of\n * eucalyptus, an allium head and a few grasses - the botanical line drawing\n * a flower shop prints on everything it hands over the counter.\n */\nfunction Bunch({ color, style }: { color: string; style?: CSSProperties }) {\n  const line = { fill: 'none', stroke: color, strokeWidth: 2.1, strokeLinecap: 'round' as const, strokeLinejoin: 'round' as const }\n  const leaf = (x: number, y: number, rot: number, len = 26) => (\n    <path key={`${x}-${y}-${rot}`} d={`M0 0c${len * 0.3} -${len * 0.5} ${len * 0.75} -${len * 0.5} ${len} 0c-${len * 0.25} ${len * 0.5} -${len * 0.7} ${len * 0.5} -${len} 0z`} transform={`translate(${x} ${y}) rotate(${rot})`} {...line} />\n  )\n  return (\n    <svg viewBox=\"0 0 220 250\" style={{ display: 'block', ...style }} aria-hidden>\n      {/* stems, gathered at the foot */}\n      <path d=\"M110 248C104 200 106 150 104 96\" {...line} />\n      <path d=\"M112 248C90 210 74 170 70 118\" {...line} />\n      <path d=\"M108 248C136 206 150 170 148 112\" {...line} />\n      <path d=\"M114 248C126 214 142 190 172 172\" {...line} strokeWidth={1.6} />\n      <path d=\"M106 248C84 226 62 212 40 208\" {...line} strokeWidth={1.6} />\n      {/* eucalyptus down the left stem */}\n      {[\n        [76, 200, -20],\n        [64, 178, -40],\n        [80, 160, 10],\n        [66, 138, -30],\n        [80, 122, 20],\n      ].map(([x, y, r]) => (\n        <circle key={`e${x}${y}`} cx={x} cy={y} r={8} transform={`rotate(${r} ${x} ${y})`} {...line} strokeWidth={1.8} />\n      ))}\n      {/* the poppy on the centre stem */}\n      <g transform=\"translate(104 78)\">\n        <path d=\"M0-30c14-6 26 4 24 16-2 14-14 20-24 14-10 6-22 0-24-14-2-12 10-22 24-16z\" {...line} />\n        <path d=\"M-10-8c6-8 14-8 20 0M-8 4c4 6 12 6 16 0\" {...line} strokeWidth={1.6} />\n        <circle cx={0} cy={-1} r={4} fill={color} />\n        {[-24, -10, 6, 20].map((a) => (\n          <path key={a} d={`M0 -1 l ${Math.cos((a * Math.PI) / 180) * 9} ${Math.sin((a * Math.PI) / 180) * 9 - 9}`} {...line} strokeWidth={1.3} />\n        ))}\n      </g>\n      {/* leaves on the centre stem */}\n      {leaf(96, 150, -150, 24)}\n      {leaf(108, 176, 20, 26)}\n      {/* the allium on the right stem */}\n      <g transform=\"translate(148 96)\">\n        <circle cx={0} cy={0} r={22} {...line} strokeWidth={1.4} strokeDasharray=\"2 5\" />\n        {Array.from({ length: 12 }, (_, i) => {\n          const a = (i * 30 * Math.PI) / 180\n          return <circle key={i} cx={Math.cos(a) * 15} cy={Math.sin(a) * 15} r={2.2} fill={color} />\n        })}\n        <circle cx={0} cy={0} r={2.4} fill={color} />\n      </g>\n      {/* grasses */}\n      <path d=\"M172 172c8-14 10-28 6-44\" {...line} strokeWidth={1.4} />\n      <path d=\"M178 128l-3 5M181 137l-4 5M176 118l-3 5\" {...line} strokeWidth={1.3} />\n      <path d=\"M40 208c-6-12-4-24 4-34\" {...line} strokeWidth={1.4} />\n      <circle cx={44} cy={174} r={3} fill={color} />\n      <circle cx={38} cy={186} r={2.4} fill={color} />\n      {/* the tie */}\n      <path d=\"M100 236c6-4 14-4 20 0M100 240c6 4 14 4 20 0\" {...line} strokeWidth={1.6} />\n    </svg>\n  )\n}",
  "package-art:Burst": "/** The printed sunburst the bowl sits on - the one flat colour a cereal front is never without. */\nfunction Burst({ p }: { p: Mill }) {\n  const rays = Array.from({ length: 18 }, (_, i) => {\n    const a0 = (i * 20 * Math.PI) / 180\n    const a1 = ((i * 20 + 9) * Math.PI) / 180\n    const r = 150\n    return `M100 100 L${100 + r * Math.cos(a0)} ${100 + r * Math.sin(a0)} L${100 + r * Math.cos(a1)} ${100 + r * Math.sin(a1)} Z`\n  }).join(' ')\n  return (\n    <svg viewBox=\"0 0 200 200\" preserveAspectRatio=\"xMidYMid meet\" style={{ position: 'absolute', inset: 0, width: '100%', height: '100%' }} aria-hidden>\n      <defs>\n        <radialGradient id=\"cereal-burst\" cx=\"50%\" cy=\"55%\" r=\"55%\">\n          <stop offset=\"0\" stopColor={p.honey} />\n          <stop offset=\"1\" stopColor={p.amber} />\n        </radialGradient>\n        <clipPath id=\"cereal-round\">\n          <circle cx={100} cy={100} r={98} />\n        </clipPath>\n      </defs>\n      <circle cx={100} cy={100} r={98} fill=\"url(#cereal-burst)\" />\n      <path d={rays} fill=\"#ffffff\" opacity={0.2} clipPath=\"url(#cereal-round)\" />\n    </svg>\n  )\n}",
  "package-art:CerealBack": "/** The back: a recipe, the rest of the range, the small print. */\nexport function CerealBack({ material }: { material: string }) {\n  const p = mill(material)\n  return (\n    <BoxFace material={material} style={{ gap: '2.6cqw' }}>\n      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', gap: '2cqw' }}>\n        <BrandTab p={p} size={2.7} />\n        <Micro style={{ fontSize: '2.6cqw', opacity: 0.75 }}>Good mornings start here</Micro>\n      </div>\n      <div style={{ fontFamily: SERIF, fontSize: '8cqw', lineHeight: 1.04, letterSpacing: '-0.015em' }}>\n        Breakfast, sorted. Try it layered.\n      </div>\n      <div\n        style={{\n          border: `0.45cqw solid ${p.ink}`,\n          borderRadius: '2.5cqw',\n          padding: '3.4cqw 3.8cqw',\n          display: 'grid',\n          gridTemplateColumns: '1fr 24cqw',\n          gap: '3cqw',\n          alignItems: 'stretch',\n        }}\n      >\n        <div style={{ display: 'flex', flexDirection: 'column', gap: '2cqw' }}>\n          <Micro style={{ fontSize: '2.6cqw', color: p.red }}>Recipe · 5 minutes · serves 1</Micro>\n          <div style={{ fontFamily: SERIF, fontStyle: 'italic', fontSize: '6.4cqw', lineHeight: 1, color: p.amber }}>Honey Oat Parfait</div>\n          <ol style={{ margin: 0, padding: 0, listStyle: 'none', display: 'grid', gap: '1.4cqw' }}>\n            {[\n              'Spoon ½ cup of yogurt into a tall glass.',\n              'Add a handful of clusters and a few berries.',\n              'Repeat, then finish with a drizzle of honey.',\n              'Eat it before the clusters go soft. They won’t take long.',\n            ].map((step, i) => (\n              <li key={step} style={{ display: 'flex', gap: '2.2cqw', ...copy('3cqw', { lineHeight: 1.32 }) }}>\n                <span style={{ color: p.red, fontWeight: 900, fontVariantNumeric: 'tabular-nums', flex: 'none' }}>{i + 1}</span>\n                <span>{step}</span>\n              </li>\n            ))}\n          </ol>\n        </div>\n        <div style={{ minHeight: 0 }}>\n          <Parfait p={p} />\n        </div>\n      </div>\n      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'baseline', marginTop: '1cqw' }}>\n        <Micro style={{ fontSize: '2.6cqw', color: p.red }}>Also from Ridgeway Mills</Micro>\n        <Micro style={{ fontSize: '2.4cqw', opacity: 0.72 }}>Look for the green tab</Micro>\n      </div>\n      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '3cqw', padding: '0 3cqw' }}>\n        <MiniBox color=\"#c8322b\" name=\"Cinnamon Crunch\" sub=\"Toasted oats · cinnamon\" ink={p.ink} />\n        <MiniBox color=\"#6b3fa0\" name=\"Berry Clusters\" sub=\"Blueberry · cranberry\" ink={p.ink} />\n        <MiniBox color=\"#7a4a1e\" name=\"Maple Pecan\" sub=\"Real maple · pecans\" ink={p.ink} />\n      </div>\n      <div style={{ flex: 1 }} />\n      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-end', gap: '3cqw' }}>\n        <Micro style={{ fontSize: '2.3cqw', opacity: 0.75, lineHeight: 1.35 }}>\n          Ridgeway Mills · Lewiston, ID 83501 · ridgewaymills.com\n          <br />\n          Made in the USA with domestic and imported ingredients\n        </Micro>\n        <RecycleMark\n          color={p.ink}\n          size=\"6cqw\"\n          label={\n            <Micro style={{ fontSize: '2.2cqw', lineHeight: 1.3 }}>\n              Recycle carton\n              <br />\n              discard liner\n            </Micro>\n          }\n        />\n      </div>\n    </BoxFace>\n  )\n}",
  "package-art:CerealFacts": "/** The right side: the Nutrition Facts panel, the ingredients, the UPC. */\nexport function CerealFacts({ material }: { material: string }) {\n  const p = mill(material)\n  return (\n    <BoxFace material={material} style={{ padding: '5cqw', gap: '3.4cqw' }}>\n      <NutritionFacts\n        compact\n        fontSize=\"6.4cqw\"\n        servings=\"About 12\"\n        servingSize=\"1 cup (55g)\"\n        calories=\"210\"\n        rows={[\n          { label: 'Total Fat', amount: '2.5g', dv: '3%', bold: true },\n          { label: 'Saturated Fat', amount: '0g', dv: '0%', indent: 1 },\n          { label: 'Trans Fat', amount: '0g', indent: 1 },\n          { label: 'Cholesterol', amount: '0mg', dv: '0%', bold: true },\n          { label: 'Sodium', amount: '190mg', dv: '8%', bold: true },\n          { label: 'Total Carbohydrate', amount: '44g', dv: '16%', bold: true },\n          { label: 'Dietary Fiber', amount: '4g', dv: '14%', indent: 1 },\n          { label: 'Total Sugars', amount: '12g', indent: 1 },\n          { label: 'Incl. 11g Added Sugars', amount: '', dv: '22%', indent: 2 },\n          { label: 'Protein', amount: '5g', bold: true },\n        ]}\n        micros={[\n          { label: 'Vitamin D', amount: '2mcg', dv: '10%' },\n          { label: 'Calcium', amount: '20mg', dv: '2%' },\n          { label: 'Iron', amount: '8.1mg', dv: '45%' },\n          { label: 'Potassium', amount: '180mg', dv: '4%' },\n        ]}\n      />\n      <p style={copy('5.5cqw', { lineHeight: 1.3 })}>\n        <strong>INGREDIENTS:</strong> WHOLE GRAIN OATS, SUGAR, RICE FLOUR, HONEY, CANOLA OIL, MOLASSES, SALT,\n        NATURAL FLAVOR, BAKING SODA, MIXED TOCOPHEROLS (FOR FRESHNESS). VITAMINS AND MINERALS: REDUCED IRON,\n        VITAMIN D3.\n      </p>\n      <p style={copy('5.5cqw', { lineHeight: 1.3 })}>\n        <strong>CONTAINS:</strong> OATS. MAY CONTAIN WHEAT AND ALMONDS.\n      </p>\n      <div style={{ flex: 1 }} />\n      <div style={{ background: '#ffffff', padding: '3cqw 2.5cqw 1cqw', alignSelf: 'center', width: '88%', boxSizing: 'border-box' }}>\n        <UpcA digits=\"03881205512\" color=\"#111111\" />\n      </div>\n      <Micro style={{ fontSize: '4.2cqw', opacity: 0.75, textAlign: 'center', color: p.ink }}>Best if used by: see top</Micro>\n    </BoxFace>\n  )\n}",
  "package-art:CerealFront": "/** The front: the tab, \"Honey Oat Clusters\", the bowl, the facts and seals, the weight. */\nexport function CerealFront({ material }: { material: string }) {\n  const p = mill(material)\n  return (\n    <BoxFace material={material} style={{ gap: '1.4cqw' }}>\n      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', gap: '2cqw' }}>\n        <BrandTab p={p} size={2.7} />\n        <Pill color={p.red} ink=\"#fff4dc\" size=\"2.6cqw\" style={{ transform: 'rotate(4deg)', marginTop: '0.4cqw' }}>\n          Family size\n        </Pill>\n      </div>\n      <div style={{ textAlign: 'center', marginTop: '0.4cqw' }}>\n        <div style={{ fontFamily: SERIF, fontStyle: 'italic', fontSize: '12cqw', lineHeight: 0.95, color: p.amber, letterSpacing: '-0.015em' }}>\n          Honey Oat\n        </div>\n        <div style={{ fontFamily: FONT, fontWeight: 900, fontSize: '16cqw', lineHeight: 0.92, letterSpacing: '-0.045em', color: p.title, marginTop: '-0.6cqw' }}>\n          CLUSTERS\n        </div>\n        <div style={{ fontSize: '3cqw', fontWeight: 600, marginTop: '1.4cqw', letterSpacing: '0.01em' }}>\n          Toasted whole grain oat clusters with a touch of real honey\n        </div>\n      </div>\n      <div style={{ flex: 1, minHeight: 0, position: 'relative', margin: '0.4cqw 0' }}>\n        <Burst p={p} />\n        {/* The hero: a photograph, as on every cereal box in the aisle. It is a\n            cut-out, so the burst prints behind it and the board shows round it. */}\n        <Photo src={asset('/art/cereal-bowl.webp')} fit=\"contain\" style={{ position: 'absolute', inset: '1% 3%', width: '94%', height: '98%' }} />\n        <div\n          style={{\n            position: 'absolute',\n            top: '4%',\n            right: '1%',\n            background: p.red,\n            color: '#fff4dc',\n            fontWeight: 800,\n            fontSize: '2.4cqw',\n            letterSpacing: '0.08em',\n            textTransform: 'uppercase',\n            padding: '1.2cqw 2cqw',\n            borderRadius: '0.6cqw',\n            transform: 'rotate(-6deg)',\n            lineHeight: 1.15,\n            textAlign: 'center',\n          }}\n        >\n          New!\n          <br />\n          <span style={{ fontWeight: 600, letterSpacing: '0.02em', textTransform: 'none', fontSize: '2.2cqw' }}>Bigger clusters</span>\n        </div>\n      </div>\n      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-end', gap: '2cqw' }}>\n        <FactsUpFront p={p} />\n        <div style={{ display: 'flex', gap: '1.6cqw' }}>\n          <RoundSeal\n            size=\"13.5cqw\"\n            legend=\"WHOLE GRAIN · 32g PER SERVING · \"\n            color={p.ink}\n            center={\n              <span style={{ fontSize: '3.6cqw', fontWeight: 900, letterSpacing: '-0.03em' }}>\n                32<span style={{ fontSize: '2.1cqw', fontWeight: 800 }}>g</span>\n              </span>\n            }\n          />\n          <RoundSeal\n            size=\"13.5cqw\"\n            legend=\"GOOD SOURCE OF FIBER · \"\n            color={p.ink}\n            center={\n              <span style={{ fontSize: '2.3cqw', fontWeight: 800, letterSpacing: '0.02em' }}>\n                4g\n                <br />\n                FIBER\n              </span>\n            }\n          />\n        </div>\n      </div>\n      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'baseline', marginTop: '0.4cqw' }}>\n        <div style={{ fontSize: '3cqw', fontWeight: 800, letterSpacing: '0.03em', whiteSpace: 'nowrap' }}>NET WT 18 OZ (1 LB 2 OZ) 510g</div>\n        <Micro style={{ fontSize: '2.1cqw', opacity: 0.72, whiteSpace: 'nowrap' }}>No artificial flavors</Micro>\n      </div>\n    </BoxFace>\n  )\n}",
  "package-art:CerealStory": "/** The left side: the mill's story, how it is made, who to call. */\nexport function CerealStory({ material }: { material: string }) {\n  const p = mill(material)\n  const steps = [\n    ['Roll', 'Whole oats, rolled thick and kept whole grain.'],\n    ['Toast', 'Baked slowly with honey until the clusters hold.'],\n    ['Pour', 'Into the box within a day. Nothing sits.'],\n  ]\n  return (\n    <BoxFace material={material} style={{ padding: '5.5cqw', gap: '4cqw' }}>\n      <BrandTab p={p} size={4.4} />\n      <div style={{ fontFamily: SERIF, fontSize: '10.5cqw', lineHeight: 1.06, letterSpacing: '-0.01em' }}>\n        Real oats, toasted in small batches since 1962.\n      </div>\n      <p style={copy('5.9cqw', { lineHeight: 1.38 })}>\n        We started as a grain mill on the Ridgeway river, and we still buy our oats from the farms up the valley.\n        Every batch is toasted in ovens you could stand in, then poured straight into the box.\n      </p>\n      <div style={{ flex: 1, minHeight: 0, position: 'relative' }}>\n        <Photo src={asset('/art/cereal-clusters.webp')} fit=\"contain\" />\n      </div>\n      <ol style={{ margin: 0, padding: 0, listStyle: 'none', display: 'grid', gap: '2.6cqw' }}>\n        {steps.map(([name, how], i) => (\n          <li key={name} style={{ display: 'flex', gap: '3cqw', ...copy('5.6cqw', { lineHeight: 1.3 }) }}>\n            <span style={{ color: p.red, fontWeight: 900, fontVariantNumeric: 'tabular-nums', flex: 'none' }}>{i + 1}</span>\n            <span>\n              <strong>{name}.</strong> {how}\n            </span>\n          </li>\n        ))}\n      </ol>\n      <p style={copy('5cqw', { lineHeight: 1.32, opacity: 0.85 })}>\n        Questions or comments? Call 1-800-555-0142 weekdays, or write to hello@ridgewaymills.com. Please have the box\n        handy.\n      </p>\n      <div style={{ display: 'flex', alignItems: 'center', gap: '3cqw' }}>\n        <RecycleMark color={p.ink} size=\"12cqw\" />\n        <Micro style={{ fontSize: '4cqw', lineHeight: 1.3, opacity: 0.8 }}>\n          Carton: recycle\n          <br />\n          Liner: discard\n        </Micro>\n      </div>\n      <Micro style={{ fontSize: '3.8cqw', opacity: 0.7, lineHeight: 1.3 }}>Made in the USA with domestic and imported ingredients · Ridgeway Mills, Lewiston, ID 83501</Micro>\n    </BoxFace>\n  )\n}",
  "package-art:CerealTop": "/** The top: the name along the flap, the best-by jetted on, \"open here\" at the front edge. */\nexport function CerealTop({ material }: { material: string }) {\n  const p = mill(material)\n  return (\n    <BoxFace material={material} style={{ flexDirection: 'row', alignItems: 'stretch', justifyContent: 'space-between', padding: '3.2cqw 4.5cqw', gap: '3cqw' }}>\n      <div style={{ display: 'flex', flexDirection: 'column', justifyContent: 'space-between', gap: '1cqw', minWidth: 0 }}>\n        <BrandTab p={p} size={2.4} />\n        <div style={{ fontFamily: SERIF, fontStyle: 'italic', fontSize: '6.4cqw', lineHeight: 1, color: p.amber, whiteSpace: 'nowrap' }}>\n          Honey Oat <span style={{ fontFamily: FONT, fontStyle: 'normal', fontWeight: 900, color: p.title, letterSpacing: '-0.04em' }}>CLUSTERS</span>\n        </div>\n        <Micro style={{ fontSize: '2.3cqw', opacity: 0.75 }}>▲ Lift tab to open · press to reclose</Micro>\n      </div>\n      <div style={{ display: 'flex', flexDirection: 'column', justifyContent: 'space-between', alignItems: 'flex-end', textAlign: 'right', flex: 'none' }}>\n        <Micro style={{ fontSize: '2.3cqw', opacity: 0.75 }}>Best if used by</Micro>\n        <JetPrint color={p.ink} size=\"4.6cqw\">\n          {'14 MAR 2027\\nLOT 3A7 K2 06:31'}\n        </JetPrint>\n        <Micro style={{ fontSize: '2.3cqw', opacity: 0.75 }}>Net wt 18 oz (510g)</Micro>\n      </div>\n    </BoxFace>\n  )\n}",
  "package-art:copy": "const copy = (size: string, extra?: CSSProperties): CSSProperties => ({\n  margin: 0,\n  fontSize: size,\n  lineHeight: 1.36,\n  ...extra,\n})",
  "package-art:FactsUpFront": "/**\n * The \"Facts Up Front\" strip: calories, saturated fat, sodium and sugars per\n * serving in four small tiles at the foot of the front. The US industry\n * scheme every major cereal has carried since 2011 - and the single detail\n * that most says \"real box\" rather than \"designed box\".\n */\nfunction FactsUpFront({ p }: { p: Mill }) {\n  const items: [string, string, string][] = [\n    ['210', 'Calories', ''],\n    ['0g', 'Sat fat', '0% DV'],\n    ['190mg', 'Sodium', '8% DV'],\n    ['12g', 'Sugars', ''],\n  ]\n  return (\n    <div>\n      <Micro style={{ fontSize: '1.9cqw', display: 'block', marginBottom: '0.9cqw', opacity: 0.8 }}>Per 1 cup serving</Micro>\n      <div style={{ display: 'flex', gap: '1.1cqw' }}>\n        {items.map(([value, label, dv]) => (\n          <div\n            key={label}\n            style={{\n              border: `0.28cqw solid ${p.ink}`,\n              borderRadius: '1.6cqw',\n              padding: '1cqw 1.3cqw 0.9cqw',\n              textAlign: 'center',\n              minWidth: '9.6cqw',\n              lineHeight: 1,\n            }}\n          >\n            <div style={{ fontWeight: 800, fontSize: '3cqw', letterSpacing: '-0.02em' }}>{value}</div>\n            <div style={{ fontSize: '1.65cqw', fontWeight: 700, letterSpacing: '0.06em', textTransform: 'uppercase', marginTop: '0.7cqw' }}>{label}</div>\n            <div style={{ fontSize: '1.55cqw', opacity: dv ? 0.75 : 0, marginTop: '0.4cqw' }}>{dv || '\\u00a0'}</div>\n          </div>\n        ))}\n      </div>\n    </div>\n  )\n}",
  "package-art:Fern": "/** A frond - the candle company's mark, cut in one colour. */\nfunction Fern({ color, style }: { color: string; style?: CSSProperties }) {\n  return (\n    <svg viewBox=\"0 0 40 60\" style={{ display: 'block', ...style }} aria-hidden>\n      <path d=\"M20 58C18 40 18 22 24 4\" stroke={color} strokeWidth={2} fill=\"none\" strokeLinecap=\"round\" />\n      {[0, 1, 2, 3, 4, 5].map((i) => (\n        <g key={i} fill={color}>\n          <path d={`M${19.6 - i * 0.3} ${48 - i * 7.5}c-7-1-11-5-13-11 6 1 11 5 13 11z`} opacity={0.95 - i * 0.05} />\n          <path d={`M${20.4 - i * 0.2} ${45 - i * 7.5}c7-2 11-6 12-12-6 2-10 6-12 12z`} opacity={0.95 - i * 0.05} />\n        </g>\n      ))}\n    </svg>\n  )\n}",
  "package-art:MailerEnd": "/** An end panel: the pictograms either side of where the tape wraps down. */\nexport function MailerEnd({ material }: { material: string }) {\n  const ink = materialTone(material).text\n  return (\n    <ShipperFace material={material} style={{ flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', padding: '4cqw 6cqw' }}>\n      <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '1.8cqw' }}>\n        <Pictogram kind=\"fragile\" color={ink} size=\"15cqw\" />\n        <Micro style={{ fontSize: '2.8cqw' }}>Fragile</Micro>\n      </div>\n      <Fern color={ink} style={{ height: '18cqw', width: 'auto', opacity: 0.9 }} />\n      <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '1.8cqw' }}>\n        <Pictogram kind=\"up\" color={ink} size=\"15cqw\" />\n        <Micro style={{ fontSize: '2.8cqw' }}>This way up</Micro>\n      </div>\n    </ShipperFace>\n  )\n}",
  "package-art:MailerFront": "/** The long front: the name and the mark, at shelf height. */\nexport function MailerFront({ material }: { material: string }) {\n  const ink = materialTone(material).text\n  return (\n    <ShipperFace material={material} style={{ flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', padding: '3cqw 4.5cqw', gap: '3cqw' }}>\n      <div style={{ display: 'flex', alignItems: 'center', gap: '2.2cqw', flex: 'none' }}>\n        <Fern color={ink} style={{ height: '12cqw', width: 'auto' }} />\n        <div style={{ fontFamily: SERIF, fontSize: '8cqw', lineHeight: 0.9, letterSpacing: '-0.02em', whiteSpace: 'nowrap' }}>Fernhaven</div>\n      </div>\n      <div style={{ textAlign: 'right', display: 'grid', gap: '1.2cqw', minWidth: 0 }}>\n        <Micro style={{ fontSize: '1.6cqw', whiteSpace: 'nowrap' }}>Hand-poured candles &amp; home goods</Micro>\n        <Micro style={{ fontSize: '1.6cqw', opacity: 0.72, whiteSpace: 'nowrap' }}>fernhaven.co · Burlington, Vermont</Micro>\n      </div>\n    </ShipperFace>\n  )\n}",
  "package-art:MailerLid": "/**\n * The lid: three zones with air between them, and nothing drawn as a line.\n * The brand sits above the tape, the handling marks below it, and the\n * header and the small print keep to the edges - the way a real shipper is\n * laid out around the tape it knows is coming.\n */\nexport function MailerLid({ material }: { material: string }) {\n  const ink = materialTone(material).text\n  const marks = [\n    ['fragile', 'Fragile'],\n    ['up', 'This way up'],\n    ['dry', 'Keep dry'],\n  ] as const\n  return (\n    <ShipperFace material={material} style={{ display: 'grid', gridTemplateRows: '1fr 24% 1fr', padding: '4.6cqw 6cqw 4.4cqw' }}>\n      <div style={{ display: 'flex', flexDirection: 'column', justifyContent: 'space-between', minHeight: 0 }}>\n        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', gap: '3cqw' }}>\n          <div style={{ display: 'flex', alignItems: 'center', gap: '1.3cqw' }}>\n            <Fern color={ink} style={{ height: '4.4cqw', width: 'auto' }} />\n            <Micro style={{ fontSize: '1.85cqw', whiteSpace: 'nowrap' }}>Fernhaven Candle Co.</Micro>\n          </div>\n          <Micro style={{ fontSize: '1.85cqw', whiteSpace: 'nowrap', opacity: 0.7 }}>Burlington, Vermont</Micro>\n        </div>\n        <div style={{ textAlign: 'center' }}>\n          <div style={{ fontFamily: SERIF, fontSize: '13cqw', lineHeight: 0.9, letterSpacing: '-0.02em' }}>Fernhaven</div>\n          <Micro style={{ fontSize: '1.9cqw', display: 'block', marginTop: '2.2cqw', whiteSpace: 'nowrap', letterSpacing: '0.32em' }}>\n            Hand-poured candles · Small batch · Since 2019\n          </Micro>\n        </div>\n      </div>\n      {/* the tape's lane, left clear */}\n      <div />\n      <div style={{ display: 'flex', flexDirection: 'column', justifyContent: 'space-between', minHeight: 0 }}>\n        <div style={{ display: 'flex', justifyContent: 'center', gap: '10cqw' }}>\n          {marks.map(([kind, label]) => (\n            <div key={kind} style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '1.5cqw' }}>\n              <Pictogram kind={kind} color={ink} size=\"7.4cqw\" />\n              <Micro style={{ fontSize: '1.8cqw', whiteSpace: 'nowrap' }}>{label}</Micro>\n            </div>\n          ))}\n          <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '1.5cqw' }}>\n            <RecycleMark color={ink} size=\"7cqw\" />\n            <Micro style={{ fontSize: '1.8cqw', whiteSpace: 'nowrap' }}>Recycle</Micro>\n          </div>\n        </div>\n        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'baseline', gap: '3cqw' }}>\n          <Micro style={{ fontSize: '1.7cqw', whiteSpace: 'nowrap', opacity: 0.7 }}>100% recycled corrugate · Soy ink · Reuse, then recycle</Micro>\n          <Micro style={{ fontSize: '1.7cqw', whiteSpace: 'nowrap', opacity: 0.7 }}>fernhaven.co</Micro>\n        </div>\n      </div>\n    </ShipperFace>\n  )\n}",
  "package-art:materialToneInverse": "/** The mark inside a filled pictogram, which is the board showing through. */\nfunction materialToneInverse(ink: string): string {\n  return ink === PAPER ? INK : PAPER\n}",
  "package-art:mill": "function mill(material: string): Mill {\n  const dark = materialTone(material).text !== INK\n  return dark\n    ? { dark, ink: PAPER, onInk: INK, green: '#2f8a5b', honey: '#f2b544', amber: '#e08a2e', title: '#f8efe0', red: '#e5574a', cream: '#fff4dc' }\n    : { dark, ink: '#3a2412', onInk: '#fff4dc', green: '#1f5c3d', honey: '#f0b233', amber: '#c9741a', title: '#3a2412', red: '#c8322b', cream: '#fff4dc' }\n}",
  "package-art:Mill": "/** The mill's inks, with a dark-board variant so a black box stays legible. */\ninterface Mill {\n  dark: boolean\n  ink: string\n  onInk: string\n  green: string\n  honey: string\n  amber: string\n  title: string\n  red: string\n  cream: string\n}",
  "package-art:MiniBox": "/** One of the range on the back, as a small front. */\nfunction MiniBox({ color, name, sub, ink }: { color: string; name: string; sub: string; ink: string }) {\n  return (\n    <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '1.4cqw', minWidth: 0 }}>\n      <svg viewBox=\"0 0 60 84\" style={{ width: '56%', display: 'block' }} aria-hidden>\n        <rect x={2} y={2} width={56} height={80} rx={2} fill=\"#fbfaf5\" stroke={ink} strokeWidth={1.3} />\n        <rect x={2.7} y={2.7} width={54.6} height={20} fill={color} />\n        <circle cx={30} cy={52} r={16} fill={color} opacity={0.18} />\n        <ellipse cx={30} cy={52} rx={14} ry={5} fill=\"#f1ede3\" stroke=\"#d8d2c4\" strokeWidth={0.8} />\n        <ellipse cx={30} cy={52} rx={11} ry={3.2} fill=\"#fffdf6\" />\n        {[22, 28, 34, 38].map((x, i) => (\n          <ellipse key={x} cx={x} cy={51 + (i % 2)} rx={2.6} ry={2} fill={i % 2 ? '#e8a63b' : '#d68a2c'} />\n        ))}\n        <path d=\"M30 52q0 16 0 20\" stroke=\"none\" />\n        <rect x={6} y={72} width={48} height={4} rx={1} fill={ink} opacity={0.35} />\n      </svg>\n      <Micro style={{ fontSize: '2.4cqw', textAlign: 'center', lineHeight: 1.25 }}>\n        {name}\n        <br />\n        <span style={{ opacity: 0.7 }}>{sub}</span>\n      </Micro>\n    </div>\n  )\n}",
  "package-art:Parfait": "/** A parfait glass, layered - the back's recipe picture. */\nfunction Parfait({ p }: { p: Mill }) {\n  return (\n    <svg viewBox=\"0 0 80 120\" style={{ display: 'block', width: '100%', height: '100%' }} aria-hidden>\n      <path d=\"M16 6h48l-6 100H22z\" fill=\"#eaf3fa\" stroke=\"#b9d5e8\" strokeWidth={1.5} />\n      <path d=\"M19 34h42l-1.3 22H20.3z\" fill=\"#fffdf6\" />\n      <path d=\"M20.3 56h39.4l-1.3 20H21.6z\" fill=\"#d68a2c\" />\n      <path d=\"M21.6 76h36.8l-1.2 18H22.8z\" fill=\"#fffdf6\" />\n      <path d=\"M22.8 94h34.4l-.8 12H23.6z\" fill=\"#b83a63\" />\n      <g fill=\"#b83a63\">\n        <circle cx={30} cy={26} r={4.5} />\n        <circle cx={41} cy={22} r={5} />\n        <circle cx={52} cy={27} r={4.2} />\n      </g>\n      <g fill=\"#e8a63b\">\n        <ellipse cx={28} cy={64} rx={3.4} ry={2.6} />\n        <ellipse cx={40} cy={68} rx={3.6} ry={2.8} />\n        <ellipse cx={52} cy={63} rx={3.2} ry={2.5} />\n      </g>\n      <path d=\"M40 8v8\" stroke={p.honey} strokeWidth={3} strokeLinecap=\"round\" />\n      <path d=\"M22 12v86\" stroke=\"#ffffff\" strokeWidth={3} opacity={0.65} strokeLinecap=\"round\" />\n    </svg>\n  )\n}",
  "package-art:Pictogram": "/** ISO handling pictograms, drawn in the ink: the glass, the arrows, the umbrella. */\nfunction Pictogram({ kind, color, size }: { kind: 'fragile' | 'up' | 'dry'; color: string; size: string }) {\n  const stroke = { fill: 'none', stroke: color, strokeWidth: 3.2, strokeLinecap: 'round' as const, strokeLinejoin: 'round' as const }\n  return (\n    <svg viewBox=\"0 0 48 48\" style={{ width: size, height: size, display: 'block', flex: 'none' }} aria-hidden>\n      {kind === 'fragile' && (\n        <g {...stroke}>\n          <path d=\"M14 6h20l-2 12a8 8 0 0 1-16 0z\" fill={color} />\n          <path d=\"M24 26v12M16 40h16\" />\n          <path d=\"M22 6l4 6-3 4 4 3\" stroke={materialToneInverse(color)} strokeWidth={1.6} />\n        </g>\n      )}\n      {kind === 'up' && (\n        <g {...stroke}>\n          <path d=\"M15 40V12M9 19l6-7 6 7\" />\n          <path d=\"M33 40V12M27 19l6-7 6 7\" />\n          <path d=\"M6 44h36\" />\n        </g>\n      )}\n      {kind === 'dry' && (\n        <g {...stroke}>\n          <path d=\"M6 24a18 18 0 0 1 36 0z\" fill={color} />\n          <path d=\"M24 24v14a3 3 0 0 0 6 0\" />\n          <path d=\"M10 34l-2 4M38 34l2 4M24 4v2\" />\n        </g>\n      )}\n    </svg>\n  )\n}",
  "package-art:ShipperFace": "/** A panel of the shipper: one ink on corrugate. */\nfunction ShipperFace({ material, style, children }: { material: string; style?: CSSProperties; children: ReactNode }) {\n  const t = materialTone(material)\n  return (\n    <Sheet tone={t} style={{ flexDirection: 'column', padding: '4.5cqw', color: t.text, ...style }}>\n      {children}\n    </Sheet>\n  )\n}",
  "package-art:shop": "/** The florist's two inks: the board's ink, and a terracotta or a gold to go with it. */\nfunction shop(material: string): { ink: string; accent: string } {\n  const t = materialTone(material)\n  return { ink: t.text, accent: t.text === INK ? '#b8532e' : '#e2b96a' }\n}",
  "package-art:Wheat": "/** An ear of wheat - the mill's mark. */\nfunction Wheat({ color, style }: { color: string; style?: CSSProperties }) {\n  return (\n    <svg viewBox=\"0 0 24 44\" style={{ display: 'block', ...style }} aria-hidden>\n      <path d=\"M12 44V14\" stroke={color} strokeWidth={2} strokeLinecap=\"round\" />\n      {[0, 1, 2, 3, 4].map((i) => (\n        <g key={i} fill={color}>\n          <ellipse cx={8} cy={12 + i * 6} rx={3.2} ry={4.6} transform={`rotate(24 8 ${12 + i * 6})`} />\n          <ellipse cx={16} cy={9 + i * 6} rx={3.2} ry={4.6} transform={`rotate(-24 16 ${9 + i * 6})`} />\n        </g>\n      ))}\n      <ellipse cx={12} cy={6} rx={3} ry={5} fill={color} />\n    </svg>\n  )\n}",
  "print-art:ChalkHoursArt": "/**\n * The other side of the sandwich board.\n *\n * A sidewalk sign is seen from both directions, and the back of a real one is\n * never blank - it carries the hours for whoever is walking the other way. It\n * is the same board and the same chalk as the menu, set as a week rather than\n * a price list so the two faces do not read as a duplicate when the sign turns.\n */\nexport function ChalkHoursArt() {\n  return (\n    <div\n      style={{\n        width: '100%',\n        height: '100%',\n        boxSizing: 'border-box',\n        padding: 24,\n        background: '#232823',\n        color: '#f0ede4',\n        display: 'flex',\n        flexDirection: 'column',\n        textAlign: 'center',\n        fontFamily: serif,\n      }}\n    >\n      <div style={{ fontSize: 26, fontStyle: 'italic' }}>Open</div>\n      <svg viewBox=\"0 0 100 8\" style={{ width: '80%', margin: '8px auto 14px' }} aria-hidden>\n        <path d=\"M2 4 Q 28 7, 52 3 T 98 5\" fill=\"none\" stroke=\"#e8b64c\" strokeWidth=\"1.6\" strokeLinecap=\"round\" />\n      </svg>\n      {[\n        ['mon – thu', '7 – 4'],\n        ['fri', '7 – 6'],\n        ['sat', '8 – 6'],\n        ['sun', '8 – 2'],\n      ].map(([days, hours]) => (\n        <div key={days} style={{ display: 'flex', justifyContent: 'space-between', fontSize: 17, padding: '7px 8px', borderBottom: '1px dashed rgba(240,237,228,0.25)' }}>\n          <span>{days}</span>\n          <span style={{ color: '#e8b64c' }}>{hours}</span>\n        </div>\n      ))}\n      <div style={{ marginTop: 'auto', fontSize: 14, color: '#b9c4b4' }}>dogs welcome ❧</div>\n    </div>\n  )\n}",
  "print-art:ChalkMenuArt": "/** Chalkboard menu for the A-frame. */\nexport function ChalkMenuArt() {\n  return (\n    <div\n      style={{\n        width: '100%',\n        height: '100%',\n        boxSizing: 'border-box',\n        padding: 24,\n        background: '#232823',\n        color: '#f0ede4',\n        display: 'flex',\n        flexDirection: 'column',\n        textAlign: 'center',\n        fontFamily: serif,\n      }}\n    >\n      <div style={{ fontSize: 30, fontStyle: 'italic' }}>Ridgeline Café</div>\n      <svg viewBox=\"0 0 100 8\" style={{ width: '80%', margin: '8px auto 14px' }} aria-hidden>\n        <path d=\"M2 5 Q 25 1, 50 4 T 98 3\" fill=\"none\" stroke=\"#e8b64c\" strokeWidth=\"1.6\" strokeLinecap=\"round\" />\n      </svg>\n      {[\n        ['flat white', '4.5'],\n        ['batch brew', '3.5'],\n        ['cardamom bun', '5'],\n        ['trail toastie', '9'],\n      ].map(([item, price]) => (\n        <div key={item} style={{ display: 'flex', justifyContent: 'space-between', fontSize: 17, padding: '7px 8px', borderBottom: '1px dashed rgba(240,237,228,0.25)' }}>\n          <span>{item}</span>\n          <span style={{ color: '#e8b64c' }}>{price}</span>\n        </div>\n      ))}\n      <div style={{ marginTop: 'auto', fontSize: 14, color: '#b9c4b4' }}>open till dusk ☀</div>\n    </div>\n  )\n}",
  "print-art:serif": "const serif = 'Georgia, \"Times New Roman\", serif'",
  "record-sleeve:ARTIST": "const ARTIST = 'The Marcus Hale Trio'",
  "record-sleeve:backTone": "/** The jacket's reverse: board, set in the same near-black. */\nconst backTone: Tone = {\n  ground: BOARD,\n  text: INK,\n  accent: FIELD,\n  palette: [BOARD, FIELD, INK],\n}",
  "record-sleeve:BOARD": "/** The paper of the back, which is uncoated board rather than a printed field. */\nconst BOARD = '#e8e0d0'",
  "record-sleeve:CATALOG": "const CATALOG = 'OBS-4014'",
  "record-sleeve:coverTone": "/** The jacket's front: an orange field, so the tone's ground IS the ink field. */\nconst coverTone: Tone = {\n  ground: FIELD,\n  text: BOARD,\n  accent: INK,\n  palette: [FIELD, INK, BOARD],\n}",
  "record-sleeve:FIELD": "/** The jacket's ground - a hot flat orange, printed as one solid. */\nconst FIELD = '#d8552a'",
  "record-sleeve:INK": "/** The ink everything is set in: not black, the warm near-black of litho. */\nconst INK = '#141210'",
  "record-sleeve:Label": "/**\n * A centre label.\n *\n * The model punches the spindle hole out of this surface, so the middle band\n * is left empty by construction: the label's own type lives in the top and\n * bottom thirds, which is also where a real one puts it. The arc a pressing\n * plant sets its label name on is the one thing not reproduced - a curved\n * baseline needs an SVG `textPath`, and at the size this is seen it would\n * read as a smudge either way.\n */\nfunction Label({ side, tracks }: { side: string; tracks: string[][] }) {\n  return (\n    <Sheet\n      tone={{ ground: LABEL, text: INK, accent: FIELD, palette: [LABEL, FIELD, INK] }}\n      /* A round label is a square surface the model masks to a circle, so the\n         type has to stay inside the inscribed circle - hence the deep padding\n         rather than the 7cqw a square face would take. */\n      style={{ flexDirection: 'column', alignItems: 'center', padding: '13cqw 12cqw', textAlign: 'center' }}\n    >\n      {/* The pattern ring: a plant's label often carries a printed band at the\n          rim. One seeded draw, because a pressed label does not animate. */}\n      <div style={{ position: 'absolute', inset: 0, opacity: 0.08, pointerEvents: 'none' }}>\n        <Pattern pattern={chase} seed={`label-${side}`} palette={[LABEL, FIELD, INK]} grid=\"11x11\" />\n      </div>\n\n      <div style={{ position: 'relative', display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '1.2cqw' }}>\n        <span style={{ fontSize: '9cqw', fontWeight: 700, letterSpacing: '-0.04em', lineHeight: 1, color: FIELD }}>\n          {LABEL_NAME}\n        </span>\n        <span style={{ fontSize: '3.4cqw', fontWeight: 700, letterSpacing: '0.16em', textTransform: 'uppercase' }}>\n          {CATALOG} · {side}\n        </span>\n      </div>\n\n      <div style={{ flex: 1, minHeight: 0 }} />\n\n      <div style={{ position: 'relative', display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '0.8cqw' }}>\n        {tracks.map(([, name, time]) => (\n          <span key={name} style={{ fontSize: '3.1cqw', fontWeight: 600, letterSpacing: '-0.01em', lineHeight: 1.15 }}>\n            {name} <span style={{ opacity: 0.5, fontVariantNumeric: 'tabular-nums' }}>{time}</span>\n          </span>\n        ))}\n        <span style={{ fontSize: '2.8cqw', fontWeight: 700, letterSpacing: '0.14em', opacity: 0.55, marginTop: '0.8cqw' }}>\n          33⅓ RPM\n        </span>\n      </div>\n    </Sheet>\n  )\n}",
  "record-sleeve:LABEL": "/** The disc's own label stock. */\nconst LABEL = '#efe7d6'",
  "record-sleeve:LABEL_NAME": "const LABEL_NAME = 'Obsidian'",
  "record-sleeve:Micro": "/** Uppercase micro-type - the catalogue numbers, the side marks, the credits. */\nfunction Micro({ children, style }: { children: ReactNode; style?: CSSProperties }) {\n  return (\n    <span\n      style={{\n        fontSize: '2.6cqw',\n        fontWeight: 700,\n        letterSpacing: '0.18em',\n        textTransform: 'uppercase',\n        lineHeight: 1,\n        ...style,\n      }}\n    >\n      {children}\n    </span>\n  )\n}",
  "record-sleeve:note": "const note = (size = '2.5cqw'): CSSProperties => ({\n  margin: 0,\n  fontSize: size,\n  lineHeight: 1.5,\n  letterSpacing: '-0.005em',\n})",
  "record-sleeve:PERSONNEL": "const PERSONNEL = [\n  ['Marcus Hale', 'piano'],\n  ['Reuben Diallo', 'bass'],\n  ['Clifford Nance', 'drums'],\n]",
  "record-sleeve:Side": "/** One side's track list: number, title, time, with the time flush right. */\nfunction Side({ label, tracks }: { label: string; tracks: string[][] }) {\n  return (\n    <div style={{ flex: 1, minWidth: 0, display: 'flex', flexDirection: 'column', gap: '1.4cqw' }}>\n      <Micro style={{ color: FIELD }}>{label}</Micro>\n      {tracks.map(([no, name, time]) => (\n        <div\n          key={no}\n          style={{ display: 'flex', alignItems: 'baseline', gap: '1.4cqw', fontSize: '2.6cqw', lineHeight: 1.28 }}\n        >\n          <span style={{ fontWeight: 700, opacity: 0.45, minWidth: '4cqw' }}>{no}</span>\n          <span style={{ fontWeight: 600, letterSpacing: '-0.01em', flex: 1, minWidth: 0 }}>{name}</span>\n          <span style={{ fontVariantNumeric: 'tabular-nums', opacity: 0.6 }}>{time}</span>\n        </div>\n      ))}\n    </div>\n  )\n}",
  "record-sleeve:SIDE_A": "const SIDE_A = [\n  ['A1', 'Late Set at the Alhambra', '7:42'],\n  ['A2', 'Cold Water Blues', '5:18'],\n  ['A3', 'Bongcheon Walk', '6:04'],\n]",
  "record-sleeve:SIDE_B": "const SIDE_B = [\n  ['B1', 'Eleven Past', '9:31'],\n  ['B2', 'For Someone Leaving', '4:47'],\n  ['B3', 'Second Chorus', '6:55'],\n]",
  "record-sleeve:SleeveBack": "/** The reverse: track lists, liner note, personnel, and the session credit. */\nexport function SleeveBack() {\n  return (\n    <Sheet tone={backTone} style={{ flexDirection: 'column', padding: '6cqw', gap: '3cqw' }}>\n      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'baseline' }}>\n        <span style={{ fontSize: '5.2cqw', fontWeight: 700, letterSpacing: '-0.035em', lineHeight: 1 }}>\n          {TITLE.join(' ')}\n        </span>\n        <Micro style={{ opacity: 0.6 }}>{CATALOG}</Micro>\n      </div>\n      <div style={{ height: '0.4cqw', background: INK, flex: 'none', opacity: 0.35 }} />\n\n      <div style={{ display: 'flex', gap: '6cqw' }}>\n        <Side label=\"Side A\" tracks={SIDE_A} />\n        <Side label=\"Side B\" tracks={SIDE_B} />\n      </div>\n\n      <div style={{ display: 'flex', gap: '6cqw', alignItems: 'flex-start' }}>\n        <div style={{ flex: 1, minWidth: 0, display: 'flex', flexDirection: 'column', gap: '2cqw' }}>\n          <p style={note()}>\n            Hale booked the room for one night and kept it for three. The trio had been playing the\n            Alhambra&apos;s late set for a year by then - the second show, the one that starts at\n            half past midnight, when nobody is listening for the tune they came in humming.\n          </p>\n          <p style={{ ...note('2.25cqw'), opacity: 0.66 }}>\n            Recorded 14-16 March 1961 at Ferrier Studio, Newark, New Jersey. Engineer: A. Ferrier.\n            Cover photograph: uncredited. Notes: T. Brandt.\n          </p>\n        </div>\n\n        <div style={{ flex: 'none', width: '28cqw', display: 'flex', flexDirection: 'column', gap: '1.6cqw' }}>\n          <Micro style={{ color: FIELD }}>Personnel</Micro>\n          {PERSONNEL.map(([who, what]) => (\n            <div key={who} style={{ fontSize: '2.6cqw', lineHeight: 1.25 }}>\n              <div style={{ fontWeight: 700, letterSpacing: '-0.01em' }}>{who}</div>\n              <div style={{ opacity: 0.6 }}>{what}</div>\n            </div>\n          ))}\n        </div>\n      </div>\n\n      <div style={{ flex: 1, minHeight: 0 }} />\n\n      {/* A 1961 sleeve's foot: no barcode, because there were none. */}\n      <div style={{ display: 'flex', alignItems: 'flex-end', justifyContent: 'space-between', gap: '4cqw' }}>\n        <div style={{ display: 'flex', flexDirection: 'column', gap: '1.2cqw' }}>\n          <span style={{ fontSize: '4.4cqw', fontWeight: 700, letterSpacing: '-0.03em', lineHeight: 1 }}>\n            {LABEL_NAME}\n            <span style={{ color: FIELD }}> Records</span>\n          </span>\n          <Micro style={{ fontSize: '2.1cqw', opacity: 0.55 }}>\n            41 Bleecker Street · New York 12 · N.Y.\n          </Micro>\n        </div>\n        <Micro style={{ fontSize: '3.4cqw', letterSpacing: '0.3em' }}>Stereo</Micro>\n      </div>\n    </Sheet>\n  )\n}",
  "record-sleeve:SleeveCover": "/**\n * Front cover. Type in the top third, the trio bled off the bottom edge.\n *\n * The photograph is wider than it is tall once cropped, and it is given the\n * full width at the foot rather than being centred: the bassist leaving the\n * left edge is what makes the field read as a field the band is standing in,\n * instead of a card they have been pasted onto.\n */\nexport function SleeveCover() {\n  return (\n    <Sheet tone={coverTone} style={{ flexDirection: 'column', padding: '7cqw', position: 'relative' }}>\n      {/* eslint-disable-next-line @next/next/no-img-element */}\n      <img\n        src={asset('/art/jazz-trio.webp')}\n        alt=\"\"\n        draggable={false}\n        style={{\n          position: 'absolute',\n          left: '-4cqw',\n          right: '-4cqw',\n          // Pushed below the sleeve's foot so the players' heads clear the\n          // title band: a record sleeve crops at the shins, it does not\n          // shrink the band to fit the frame.\n          bottom: '-11cqw',\n          width: '108cqw',\n          // 1000 x 993 in the file\n          aspectRatio: '1000 / 993',\n          objectFit: 'contain',\n          objectPosition: '50% 100%',\n          // The cut-out is already monochrome; this only deepens the blacks so\n          // they hold against a ground this saturated.\n          filter: 'grayscale(1) contrast(1.12) brightness(0.98)',\n          pointerEvents: 'none',\n        }}\n      />\n\n      <div style={{ position: 'relative', display: 'flex', flexDirection: 'column', gap: '2.4cqw' }}>\n        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'baseline' }}>\n          <Micro style={{ color: BOARD }}>{LABEL_NAME}</Micro>\n          <Micro style={{ color: BOARD, opacity: 0.8 }}>{CATALOG} · Stereo</Micro>\n        </div>\n        <div style={{ height: '0.5cqw', background: BOARD, flex: 'none', opacity: 0.9 }} />\n        <h2\n          style={{\n            margin: 0,\n            marginTop: '1.5cqw',\n            fontSize: '13.5cqw',\n            fontWeight: 700,\n            letterSpacing: '-0.05em',\n            lineHeight: 0.9,\n            color: BOARD,\n            whiteSpace: 'pre-line',\n          }}\n        >\n          {TITLE.join('\\n')}\n        </h2>\n        <span\n          style={{\n            fontSize: '5cqw',\n            fontWeight: 700,\n            letterSpacing: '-0.02em',\n            lineHeight: 1,\n            // Cream, like the title: the artist line lands on the drum kit,\n            // and near-black ink disappeared into it. Only the flat ground\n            // below the photograph would carry dark ink, and the type does\n            // not live there.\n            color: BOARD,\n          }}\n        >\n          {ARTIST}\n        </span>\n      </div>\n    </Sheet>\n  )\n}",
  "record-sleeve:SleeveLabelA": "export const SleeveLabelA = () => <Label side=\"Side A\" tracks={SIDE_A} />",
  "record-sleeve:SleeveLabelB": "export const SleeveLabelB = () => <Label side=\"Side B\" tracks={SIDE_B} />",
  "record-sleeve:TITLE": "const TITLE = ['Late Set', 'at the', 'Alhambra']",
  "surface-art:SurfaceArt": "/**\n * The artwork the prop explorer prints onto a mockup's surfaces: the area\n * wordmark over a green field, labelled with whichever region it fills. Print\n * and packaging objects have several panels, so the label is what tells the\n * back cover from the spine while you turn the object around.\n */\nexport function SurfaceArt({ label }: { label: string }) {\n  return (\n    <div className=\"mx-surface-art\">\n      <span className=\"mx-surface-art-label\">{label}</span>\n      {/* eslint-disable-next-line @next/next/no-img-element */}\n      <img className=\"mx-surface-art-mark\" src={asset('/assets/area_ag_white.svg')} alt=\"area\" />\n    </div>\n  )\n}",
  "swiss-art:FONT": "export const FONT = 'var(--font-inter), Inter, system-ui, -apple-system, \"Segoe UI\", sans-serif'",
  "swiss-art:INK": "export const INK = '#141414'",
  "swiss-art:luminance": "/** sRGB relative luminance, 0 (black) to 1 (white). */\nfunction luminance(hex: string): number {\n  const h = hex.replace('#', '')\n  const n =\n    h.length === 3\n      ? [...h].map((c) => Number.parseInt(c + c, 16))\n      : [0, 2, 4].map((i) => Number.parseInt(h.slice(i, i + 2), 16))\n  const [r, g, b] = n.map((v) => {\n    const c = v / 255\n    return c <= 0.04045 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4\n  }) as [number, number, number]\n  return 0.2126 * r + 0.7152 * g + 0.0722 * b\n}",
  "swiss-art:materialTone": "/**\n * Ink on the object's own material, rather than a sheet laid over it.\n *\n * A solid ground works on a screen, which is its own surface, but on a bag or\n * a shipping box it paints out the thing it is printed on: the carousel's\n * finish swatches move kraft to charcoal to olive and the printed panel stays\n * the same rectangle of ink, which is exactly backwards - the finish is the\n * material the artwork sits on. Leaving the ground transparent lets the board\n * through, and the ink flips with the material's luminance the way a real job\n * does: dark ink on kraft, white ink on charcoal.\n *\n * The threshold is 0.35 rather than 0.5 because the marks are large flat\n * shapes: mid-tone boards (olive, slate) carry white better than the contrast\n * ratio alone suggests.\n */\nexport function materialTone(material: string, accent: string = SIGNAL): Tone {\n  const ink = luminance(material) < 0.35 ? PAPER : INK\n  return { ground: 'transparent', text: ink, accent, palette: ['transparent', ink, accent] }\n}",
  "swiss-art:Micro": "/** Uppercase micro-type: the index, the section, the colophon. */\nexport function Micro({ children, style }: { children: ReactNode; style?: CSSProperties }) {\n  return (\n    <span\n      style={{\n        fontSize: '3.1cqmin',\n        fontWeight: 600,\n        letterSpacing: '0.18em',\n        textTransform: 'uppercase',\n        lineHeight: 1,\n        ...style,\n      }}\n    >\n      {children}\n    </span>\n  )\n}",
  "swiss-art:PAPER": "export const PAPER = '#efede6'",
  "swiss-art:Pattern": "/**\n * The pattern block.\n *\n * `fit=\"cover\"` rather than the default grid fit: the authored `grid` option\n * is the composition here - a poster wants a countable number of large marks,\n * not a texture that gets denser as the surface gets bigger - and `cover`\n * keeps that grid whatever shape the face turns out to be.\n *\n * `live` is the difference between a screen and a printed thing. A screen\n * takes a new seed every `RESEED_MS`, which is the whole point of the surface\n * being real DOM rather than a texture: nothing about a picture that redraws\n * itself on a phone you are dragging around in 3D is bakeable. Print does not\n * get it - a milk carton that reprinted itself every two seconds would be\n * saying something false about what the library does to a milk carton.\n *\n * The two are mutually exclusive by construction, because `redrawInterval`\n * only drives the seed while the seed is uncontrolled: a live surface passes\n * no `seed` and takes a fresh one per mount, a printed one pins it so a slot\n * scrolling out of the render window and back comes back as the same picture.\n *\n * Tabbied drops ticks under `prefers-reduced-motion`, on a hidden tab, and for\n * anything scrolled out of view, so none of this runs when it should not.\n */\nexport function Pattern({\n  pattern,\n  seed,\n  palette,\n  grid,\n  live,\n}: {\n  pattern: PatternDefinition\n  seed?: string\n  palette: string[]\n  grid: string\n  live?: boolean\n}) {\n  return (\n    <TabbiedPattern\n      pattern={pattern}\n      {...(live ? { redrawInterval: RESEED_MS } : { seed })}\n      palette={palette}\n      options={{ grid }}\n      fit=\"cover\"\n      style={{ width: '100%', height: '100%' }}\n    />\n  )\n}",
  "swiss-art:RESEED_MS": "/**\n * How often a screen redraws itself.\n *\n * Short enough to be caught rather than waited for - the carousel gives each\n * object about six seconds before it advances, so a screen repaints twice\n * while it is on stage - and long enough that each composition is a picture\n * you looked at rather than a flicker.\n */\nconst RESEED_MS = 2600",
  "swiss-art:rule": "export const rule = (color: string): CSSProperties => ({\n  height: '0.5cqmin',\n  minHeight: 1,\n  background: color,\n  flex: 'none',\n})",
  "swiss-art:sheet": "export const sheet = (tone: Tone): CSSProperties => ({\n  width: '100%',\n  height: '100%',\n  boxSizing: 'border-box',\n  containerType: 'size',\n  background: tone.ground,\n  color: tone.text,\n  fontFamily: FONT,\n  display: 'flex',\n  overflow: 'hidden',\n  userSelect: 'none',\n})",
  "swiss-art:Sheet": "/**\n * The sheet as an element, with the layout INSIDE it.\n *\n * Container-relative units on an element resolve against its nearest\n * ancestor container, never against the element itself, so a `padding: 5cqw`\n * set on the container root falls back to the viewport and comes out as 5 %\n * of the browser window - which is how a 55 mm side panel got 140 px of\n * padding and set its type at zero. Two elements, then: the outer is the\n * query container, the inner lays out in the units the outer defines.\n */\nexport function Sheet({ tone, style, children }: { tone: Tone; style?: CSSProperties; children: ReactNode }) {\n  return (\n    <div style={sheet(tone)}>\n      <div style={{ width: '100%', height: '100%', boxSizing: 'border-box', display: 'flex', minWidth: 0, minHeight: 0, ...style }}>\n        {children}\n      </div>\n    </div>\n  )\n}",
  "swiss-art:SIGNAL": "export const SIGNAL = '#e1341e'",
  "swiss-art:SwissBill": "export const SwissBill = () => (\n  <SwissStack\n    pattern={dipole}\n    seed=\"poster-bill\"\n    tone=\"ultramarine\"\n    grid=\"6x9\"\n    index=\"15\"\n    kicker=\"Konzert\"\n    title={'Signal\\n/ Noise'}\n    meta=\"Sa 22.08 · 21 Uhr\"\n  />\n)",
  "swiss-art:SwissChecker": "export const SwissChecker = () => (\n  <SwissStack\n    pattern={damier}\n    live\n    tone=\"sea\"\n    grid=\"6x9\"\n    index=\"07\"\n    kicker=\"Damier\"\n    title={'Black\\nwhite'}\n    meta=\"Positive & negative\"\n  />\n)",
  "swiss-art:SwissDial": "/**\n * The watch face. A dial is barely a hundred pixels across on the carousel, so\n * it gets one coarse pattern and one number - anything with a hierarchy in it\n * would be mush at that size.\n */\nexport function SwissDial({\n  pattern,\n  seed,\n  live,\n  tone = 'ink',\n  material,\n  accent,\n  grid = '2x3',\n  kicker,\n  title,\n}: Omit<SwissProps, 'index' | 'meta'> & { index?: string; meta?: string }) {\n  const t = material ? materialTone(material, accent) : TONES[tone]\n  return (\n    <div style={{ ...sheet(t), position: 'relative', alignItems: 'flex-end' }}>\n      <div style={{ position: 'absolute', inset: 0 }}>\n        <Pattern pattern={pattern} seed={seed} live={live} palette={t.palette} grid={grid} />\n      </div>\n      <div\n        style={{\n          position: 'relative',\n          width: '100%',\n          padding: '9cqmin',\n          /* Solid under the type, fading only where it meets the pattern: at\n             this size a wash the marks show through is a wash the time is\n             unreadable on. */\n          background: `linear-gradient(to top, ${t.ground} 72%, transparent)`,\n        }}\n      >\n        {/* A dial is ~200px across, so the micro-type has to be set larger\n            here in proportion than it is on a sheet ten times the size. */}\n        <Micro style={{ color: t.accent, fontSize: '5cqmin' }}>{kicker}</Micro>\n        <Title style={{ fontSize: '22cqmin', marginTop: '2cqmin' }}>{title}</Title>\n      </div>\n    </div>\n  )\n}",
  "swiss-art:SwissDialA": "export const SwissDialA = () => (\n  <SwissDial pattern={gyre} live tone=\"electric\" grid=\"4x6\" kicker=\"Zürich\" title=\"9:41\" />\n)",
  "swiss-art:SwissEpicentre": "export const SwissEpicentre = () => (\n  <SwissStack\n    pattern={epicentre}\n    live\n    tone=\"plum\"\n    grid=\"6x9\"\n    index=\"06\"\n    kicker=\"Zentrum\"\n    title={'Point\\nsource'}\n    meta=\"Kunsthalle · Saal 4\"\n  />\n)",
  "swiss-art:SwissField": "export const SwissField = () => (\n  <SwissStack\n    pattern={dipole}\n    live\n    tone=\"moss\"\n    grid=\"8x12\"\n    index=\"04\"\n    kicker=\"Feld\"\n    title={'Line\\nfield'}\n    meta=\"Studies in radiance\"\n  />\n)",
  "swiss-art:SwissProps": "export interface SwissProps {\n  pattern: PatternDefinition\n  /** Pinned for a printed face; omitted on a live one, which reseeds itself. */\n  seed?: string\n  /** A screen: repaints on a timer instead of holding one composition. */\n  live?: boolean\n  tone?: ToneName\n  /**\n   * Print straight onto the object instead of onto a sheet: the ground goes\n   * transparent so this colour - the object's own finish - shows through, and\n   * the ink is chosen to sit on it. Wins over `tone`.\n   */\n  material?: string\n  /** The second mark on a material print, where there is no tone to bring one. */\n  accent?: string\n  /** Coarse on a small face, finer on a large one - see each caller. */\n  grid?: string\n  index: string\n  kicker: string\n  /** Newlines are kept: the line breaks are part of the setting. */\n  title: string\n  meta: string\n}",
  "swiss-art:SwissRaster": "export const SwissRaster = () => (\n  <SwissStack\n    pattern={halftone}\n    live\n    tone=\"ember\"\n    grid=\"6x9\"\n    index=\"02\"\n    kicker=\"Raster\"\n    title={'Half\\ntone'}\n    meta=\"Plate 02 · 175 lpi\"\n  />\n)",
  "swiss-art:SwissRhythm": "export const SwissRhythm = () => (\n  <SwissSplit\n    pattern={chase}\n    live\n    tone=\"graphite\"\n    grid=\"6x9\"\n    index=\"08\"\n    kicker=\"Rhythmus\"\n    title={'Bar\\nafter bar'}\n    meta=\"Typografische Monatsblätter\"\n  />\n)",
  "swiss-art:SwissRotation": "export const SwissRotation = () => (\n  <SwissStack\n    pattern={gyre}\n    live\n    tone=\"midnight\"\n    grid=\"6x9\"\n    index=\"01\"\n    kicker=\"Rotation\"\n    title={'Slow\\nturns'}\n    meta=\"Neue Grafik · Zürich\"\n  />\n)",
  "swiss-art:SwissSplit": "/**\n * Landscape sheet: the type takes the left third and the picture the rest, so\n * a wide face reads as two columns rather than as a stretched portrait.\n */\nexport function SwissSplit({\n  pattern,\n  seed,\n  live,\n  tone = 'paper',\n  material,\n  accent,\n  grid = '4x6',\n  index,\n  kicker,\n  title,\n  meta,\n}: SwissProps) {\n  const t = material ? materialTone(material, accent) : TONES[tone]\n  return (\n    <div style={{ ...sheet(t), flexDirection: 'row' }}>\n      <div\n        style={{\n          width: '34%',\n          padding: '6cqmin',\n          paddingTop: 'calc(var(--mockup-safe-area-top, 0px) + 6cqmin)',\n          display: 'flex',\n          flexDirection: 'column',\n          gap: '3cqmin',\n        }}\n      >\n        <Micro style={{ color: t.accent }}>{index}</Micro>\n        <div style={rule(t.text)} />\n        <Micro>{kicker}</Micro>\n        <Title style={{ fontSize: '9cqmin', marginTop: 'auto' }}>{title}</Title>\n        <Micro style={{ opacity: 0.72 }}>{meta}</Micro>\n      </div>\n      <div style={{ flex: 1, minHeight: 0, position: 'relative' }}>\n        <Pattern pattern={pattern} seed={seed} live={live} palette={t.palette} grid={grid} />\n      </div>\n    </div>\n  )\n}",
  "swiss-art:SwissStack": "/**\n * Portrait sheet: colophon at the top, the picture in the middle, the type\n * block on the baseline. The classic Zurich concert bill.\n */\nexport function SwissStack({\n  pattern,\n  seed,\n  live,\n  tone = 'paper',\n  material,\n  accent,\n  grid = '4x6',\n  index,\n  kicker,\n  title,\n  meta,\n}: SwissProps) {\n  const t = material ? materialTone(material, accent) : TONES[tone]\n  return (\n    <Sheet\n      tone={t}\n      style={{\n        flexDirection: 'column',\n        padding: '7cqmin',\n        /* Clear the system bar, then the sheet's own margin again below it, so\n           the colophon is never merely touching the band. The custom property\n           is the device's - `0px` on a printed face, which is what makes one\n           layout right on a phone and on a poster. */\n        paddingTop: 'calc(var(--mockup-safe-area-top, 0px) + 7cqmin)',\n        gap: '4cqmin',\n      }}\n    >\n      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'baseline' }}>\n        <Micro style={{ color: t.accent }}>{index}</Micro>\n        <Micro>{kicker}</Micro>\n      </div>\n      <div style={{ flex: 1, minHeight: 0, position: 'relative' }}>\n        <Pattern pattern={pattern} seed={seed} live={live} palette={t.palette} grid={grid} />\n      </div>\n      <Title>{title}</Title>\n      <Micro style={{ opacity: 0.72 }}>{meta}</Micro>\n    </Sheet>\n  )\n}",
  "swiss-art:Title": "/** The one big thing on the sheet. Flush left, tight, never centred. */\nfunction Title({ children, style }: { children: ReactNode; style?: CSSProperties }) {\n  return (\n    <h2\n      style={{\n        margin: 0,\n        fontSize: '13cqmin',\n        fontWeight: 700,\n        letterSpacing: '-0.04em',\n        lineHeight: 0.92,\n        color: 'inherit',\n        whiteSpace: 'pre-line',\n        ...style,\n      }}\n    >\n      {children}\n    </h2>\n  )\n}",
  "swiss-art:tone": "const tone = (ground: string, text: string, accent: string, ...marks: string[]): Tone => ({\n  ground,\n  text,\n  accent,\n  palette: [ground, ...marks],\n})",
  "swiss-art:Tone": "export interface Tone {\n  ground: string\n  text: string\n  /** The one loud colour on the sheet: the index, the kicker, the last mark in the pattern. */\n  accent: string\n  /** Palette handed to the pattern: background first, then its marks. */\n  palette: string[]\n}",
  "swiss-art:ToneName": "export type ToneName = keyof typeof TONES",
  "swiss-art:TONES": "/**\n * The carousel's palettes, one per piece. Each is a ground, an ink that\n * reads on it, an accent, and the marks the pattern draws in - two or three,\n * because a poster is a few flat colours, not a gradient. Light grounds\n * alternate with dark ones down the strip so neighbouring screens never read\n * as the same sheet.\n */\nexport const TONES = {\n  paper: tone(PAPER, INK, SIGNAL, INK, SIGNAL),\n  ink: tone(INK, PAPER, SIGNAL, PAPER, SIGNAL),\n  /** Cyan and white on navy. */\n  midnight: tone('#0f1b33', '#e8eefc', '#5ec8ff', '#5ec8ff', '#e8eefc', '#3560d6'),\n  /** Orange and amber on near-black. */\n  ember: tone('#1a1412', '#f6e7d8', '#ff7a45', '#ff7a45', '#f2b544', '#f6e7d8'),\n  /** The Bauhaus primaries on cream. */\n  cobalt: tone('#f1ede2', '#1f2a5a', '#e0402c', '#1f43c9', '#f0b323', '#e0402c'),\n  /** Lime on bottle green. */\n  moss: tone('#0f2e22', '#e6f2d9', '#b8e04a', '#b8e04a', '#e6f2d9', '#2f8f5b'),\n  /** Orange, ink and a blue on warm white. */\n  tangerine: tone('#f4efe6', '#26221f', '#ff6a1a', '#ff6a1a', '#26221f', '#2b6fd6'),\n  /** Coral and lilac on aubergine. */\n  plum: tone('#2a1738', '#f5e9f7', '#ff8fa3', '#ff8fa3', '#f5e9f7', '#9b5de5'),\n  /** Teal and apricot on sea glass. */\n  sea: tone('#e6f0ee', '#0f3d3e', '#f4a259', '#0f8b8d', '#0f3d3e', '#f4a259'),\n  /** One electric blue on black - the dial. */\n  electric: tone('#0b0f19', '#f0f4ff', '#3d7bff', '#3d7bff', '#f0f4ff'),\n  /** Terracotta on plaster - the other dial. */\n  terracotta: tone('#f7ede2', '#4a2c1f', '#c65d3b', '#c65d3b', '#4a2c1f'),\n  /** Yellow and white on graphite. */\n  graphite: tone('#232629', '#f5f5f0', '#ffd23f', '#ffd23f', '#f5f5f0', '#8a8f98'),\n  /** Gold on black - the record sleeve. */\n  gold: tone('#111111', '#f3e9c9', '#d4a744', '#d4a744', '#f3e9c9'),\n  /** Ultramarine and red on off-white - the concert bill. */\n  ultramarine: tone('#f3f1ea', '#11205e', '#e63b2e', '#1b3fbf', '#e63b2e'),\n} satisfies Record<string, Tone>",
}

